/* Mazo: Código de Edificación de Viedma (2018) — Arts. 1 a 106
   Cada add(artículo, tipo, pregunta, respuesta) es un núcleo funcional. */
(window.DECKS = window.DECKS || []).push({
id: "viedma",
idp: "",            // prefijo de identificadores (vacío por compatibilidad con el progreso anterior)
title: "Código de Edificación de Viedma",
sub: "2018 · Artículos 1 a 106",
head: "Código de Edificación · Viedma 2018",
arts: {
1:"Este Código tiene por objeto regular la realización de obras de edificación, fueran de construcción, modificación (ampliación o alteración), refacción y/o demolición.",
2:"Su ámbito de aplicación se extiende al municipio de Viedma y será puesto en vigencia de acuerdo a lo establecido por la Ley Nº 929 y su Modificatoria Nº 1373, Nº 1440, Nº 1553 y Decreto Reglamentario Nº 492/82 o las que la modifiquen o sustituyan.",
3:"Actuará como Organismo de Aplicación de este Código la Municipalidad de Viedma a través de sus oficinas competentes.\nCorresponderá al Organismo de Aplicación de este Código exigir el cumplimiento de los objetivos y normas sancionando las reglamentaciones que considere necesarias.",
4:"A los fines de aplicación de este Código, entiéndase por:\nAcera: Espacio de la calle entre la línea Municipal y la calzada, destinado al tránsito de peatones.\nAlero: Plano horizontal no accesible destinado exclusivamente para resguardo de vanos y muros.\nBalcón: Elemento accesible y transitable, voladizo o no, generalmente prolongación del entrepiso y limitado por un parapeto o baranda.\nCalle: Banda vial de dominio público delimitada entre líneas municipales.\nConducto: Espacio dispuesto para contener tuberías, conducir o evacuar aire, gases, líquidos o sólidos.\nCalzada: Espacio de calle entre aceras enfrentadas, destinadas al tránsito de vehículos.\nEje divisorio: Delimitación entre parcelas de dominio privado.\nEntrepiso: Estructura resistente horizontal.\nEstructura: Armazón o esqueleto y todo elemento resistente de un edificio.\nLínea Municipal (L.M.): Delimitación entre dominio público municipal y el dominio privado.\nLocal: Cada una de las partes cubiertas cerradas en que se divide un edificio.\nLocal habitable: El destinado para propósitos normales de habitación, morada, trabajo, o permanencia continuada de personas con exclusión de lavaderos, cuartos de baño, despensas, pasajes, vestíbulos, depósitos o similares.\nMarquesinas: Alero que avanza sobre un acceso, generalmente ubicado sobre la vía pública.\nMuro: Cerramiento vertical apto para soportar cargas.\nPiso: Espacio comprendido entre el nivel de un solado y el nivel del techo siguiente sobrepuesto.\nSolado: Revestimiento del suelo natural o de un entrepiso.\nSótano: Piso situado bajo el nivel del suelo.\nTabique: Cerramiento vertical no portante.",
5:"Se considera zonificada la localidad de Viedma conforme a las disposiciones del respectivo Código Urbanístico, a los fines de la aplicación de las normas de este Código.",
6:"Los siguientes Reglamentos técnicos forman parte de este código:\n1 - Reglamento Técnico de Fundaciones (CE de la Ciudad de Buenos Aires).\n2 - Reglamento Técnico de Estructuras (CE de la Ciudad de Buenos Aires).\n3 - Proyecto de Reglamento Argentino para Estructuras de Hormigón (PRAEH).\n4 - Reglamento Técnico de Instalaciones Eléctricas (CE de la Ciudad de Buenos Aires).\n5 - Reglamento de O.S.N. o las normas que especifique el Departamento Provincial de Aguas.\n6 - Reglamento de Gas del Estado.\n7 - Reglamento de Agua y Energía de la Nación.\n8 - Reglamento Técnico de Ascensores y Transportadores (CE de la Ciudad de Buenos Aires).\n9 - Normas mínimas de Habitabilidad (SEDUV).\n10 - Normas mínimas de Habitabilidad Higrotérmica (SEDUV).\n11 - Normas de Edificación establecidas por la Secretaría de Estado y Turismo de la Nación (para la construcción de hoteles, moteles, residenciales y hosterías).",
7:"Las obras que se construyan destinadas a habitación deberán ser de carácter permanente.",
8:"Las obras de carácter transitorio deberán justificar su finalidad y contar con autorización expresa de la Municipalidad de Viedma – quien podrá exigir las condiciones mínimas de habitabilidad y saneamiento que considere necesarias.",
9:"No se permitirán construcciones de carácter precario, así como tampoco las hechas de adobe.",
10:"En todas las edificaciones deberán cumplimentarse según las zonas de que se trate, los factores de edificación y ocupación previstos por el Código Urbanístico correspondiente.",
11:"La línea de edificación no podrá avanzar sobre la línea municipal hasta los 2,70m de altura. A partir de esa altura se permitirán salientes para balcones o locales de hasta 1,00m medidas desde la línea municipal y hasta 0,15m del eje divisorio de la propiedad. En caso de ochava la saliente será paralela a la misma.",
12:"En los balcones se podrán ejecutar cerramientos opacos que no superen los 0,90m de altura, medidos desde el solado de los mismos.",
13:"En los balcones que tengan tres lados libres, se permitirá la colocación de pantallas móviles traslúcidas, cribadas o similares que produzcan cerramiento parcial, siempre que este cerramiento cubra como máximo el 50% del perímetro libre.",
14:"Los aleros o marquesinas en planta baja se mantendrán por encima de los 2,40m medidas desde el nivel de vereda y su borde exterior distará del cordón de la vereda como mínimo 0,80m. Se permitirá toldo/pérgola en retiro de frente de 4.00m, ubicado en espacio de estacionamiento.\nSobre los ejes medianeros, el muro divisorio que quedará dentro de la superficie de retiro no podrá superar los 0.60m de altura a partir de los donde se podrá materializar con rejas.\nEl cerco verde de medianeras, se permite con acuerdo de vecinos por escrito.",
15:"En lotes baldíos en determinadas zonas, la Municipalidad podrá exigir la construcción de cercos y muros divisorios cuando lo considere conveniente.\nLos cercos y muros divisorios serán ejecutados en albañilería de ladrillos comunes, bloques huecos o piedra, o c/hormigón simple o armado y deberán tener una altura mínima de 2,00m. y una altura máxima de 2,50m.",
16:"En toda nueva edificación se deberá dar un adecuado tratamiento arquitectónico a las fachadas y a los muros divisorios que queden a la vista desde la vía pública.",
17:"Es obligatorio el revoque y pintado de las fachadas en la zona urbanizada, salvo que el estilo arquitectónico o la naturaleza del material de las fachadas se oponga a ello (como ser ladrillos a la vista, o piedras lajas). En este caso los materiales empleados deberán proteger al muro de fachada contra los agentes atmosféricos.",
18:"Sobre las vías pavimentadas o enripiadas deberán construirse aceras con las características generales que se determinan reglamentariamente. El Organismo de Aplicación podrá exigir en casos especiales, el tratamiento diferenciado de las aceras en algunos entornos y/o sectores particulares de la ciudad, según proyecto particularizado.",
19:"Es obligatoria la construcción y terminación de las aceras con materiales antideslizantes de un ancho mínimo de 1.00 m, quedando terminantemente prohibido los desniveles en sentido transversal. Es obligatorio construir en las esquinas recesos para discapacitados, de acuerdo a las normas vigentes al respecto.",
20:"Cuando las aceras tengan un ancho superior a los 3,00m y el carácter de la vía o el sector lo aconsejen, la Municipalidad de Viedma podrá exigir que se dejen franjas verdes contiguas al cordón de la vereda de no menos de 1,00m. En estos casos se interrumpirán tanto en las esquinas (hasta 9,00m medidos desde la intersección de los cordones), como cuando correspondan con paradas de ómnibus o accesos o guardacoches.",
21:"Es obligatoria la construcción de cazuelas para arbolado las que serán cuadradas de 0.80 m de lado y distarán 0.20 m del cordón. Los bordes de estas cazuelas se protegerán con un cordón de 0.10 m de espesor que no podrá sobrepasar el nivel de vereda. La distancia de entre huecos deberá ser de 5.00 m.\nEs obligatoria la plantación de especies arbóreas adecuadas, las que serán determinadas por la oficina técnica correspondiente del municipio previa solicitud expresa.",
22:"El nivel de la acera estará en relación con el de la calzada y será fijado en cada caso por el Organismo de Aplicación. La pendiente transversal será del 0,2% al 0,5%, salvo en las entradas de vehículos donde se admitirán pendientes de hasta el 10%. Los cordones de las aceras no podrán, en principio, ser afectados por recesos, destinados a estacionamiento u otros fines semejantes que afecten a su continuidad. Sólo la Municipalidad, atendiendo a razones de interés general podrá disponer lo contrario.\nNo se admite escalón en veredas contiguas. En caso de diferencia de nivel en la vereda existente se deberá salvar con rampas de 2% al 5%.",
23:"La Municipalidad de Viedma podrá exigir el cumplimiento de las normas particulares según el carácter de la vía adjuntando como mínimo las normas establecidas en los Arts precedentes.\n(Ver ANEXO II Gráficos 3 y 4)",
24:"Los patios que sirven para proporcionar iluminación y ventilación a los locales se clasifican según sus dimensiones y función, como:\n• Patios de 1º Categoría: el que sirve a locales de primera, tercera y quinta clase.\n• Patios de 2º Categoría: el que sirve a locales de segunda clase.\nA los efectos de este Código, los locales se clasifican como sigue:\n• Locales de 1º Clase: Dormitorio, comedor, sala, sala común (living-room), biblioteca, estudio, consultorio, oficina, escritorio y todo local habitable no clasificado de otro modo en este Código.\n• Locales de 2º Clase: Cocina, cuarto de baño, orinal, lavadero guardarropa o vestuario colectivo, cuarto de costura, cuarto de planchar.\n• Locales de 3º Clase: Local para comercio y/o trabajo, depósito comercial y/o industrial, vestuario colectivo en club y/o asociación, gimnasio y demás locales usados para practicar deportes, cocina de: hotel, restaurante, casa de cocina, comedor colectivo y similares.\n• Locales de 4º Clase: Pasaje, corredor, vestíbulo, salita de espera anexa a oficinas o consultorio, guardarropa, cuarto de roperos y de vestir anexo a dormitorio, tocador, despensa, ante-comedor o espacio para cocinar, depósito no comercial, ni industrial, depósito de no más de 250 m2 de área anexa o dependiente de local, siempre que forme con éste una sola unidad de uso, sala de cirugía, sala de rayos x, laboratorio para procesos fotográficos.\n• Locales de 5º Clase: Locales auxiliares para servicios generales del edificio, como ser: portería, administración, cuarto de máquinas, dependencias del personal de servicios, salas comunes de juegos infantiles. Estos locales tendrán medios de salida sobre pasajes y corredores generales o públicos y no directos sobre vía pública.\nEl Organismo de Aplicación puede presumir el destino de los locales de acuerdo a su exclusivo criterio: además clasificará por analogía con alguna de las establecidas en “Clasificación de locales”, cualquier local no incluido en dicho artículo.",
25:"Los patios que sean proyectados para iluminación y/o ventilación de locales, deberán cumplir las normas que a continuación se establecen.",
26:"Los patios de primera categoría deberán ser de dimensiones tales que:\n• Permitan inscribir dentro de su superficie un círculo de diámetro: D: 1/5 H. Siendo H la distancia entre el piso del local a ventilar en el arranque del patio, hasta el nivel del techo.\n• No den a “D” un valor inferior a 3,00m.\n• El área del patio no será inferior a 12 m2.\n• En caso de unidades funcionales enfrentadas, el lado mínimo del patio en común será de 4m.",
27:"Los patios de segunda categoría, tendrán en su arranque un área mínima de 8,00m2 y en ningún caso su ancho será menor de 2,00m. En toda su altura.",
28:"A los fines de efectuar la medición de los patios, los mismos se tomarán en la proyección horizontal del edificio, excluyendo aleros, cornisas, escaleras, espesores de muros medianeros, voladizos, etc.\nEn todos los casos estos patios, deberán ser accesibles para su limpieza y no podrán ser techados, salvo con toldos móviles.",
29:"Todos los locales a construir deberán ajustarse a las siguientes dimensiones mínimas:\nEn viviendas permanentes:\n- De un solo local habitable: 18m2 de área y 3,00m de lado.\n- De dos o más locales habitables: por lo menos uno tendrá 12m2 de área y 3m de lado, los demás 8m2 de área y 2,00m de lado.\nResidencias de carácter transitorio: Se adoptarán las normas establecidas por la Secretaría de Estado de Turismo de la Nación, observándose como mínimo para: hoteles, pensiones, hostería, posadas, etc.:\n- Habitaciones individuales: 7,50m2 de área y 2,50m de lado.\n- Para dos personas: 9m2 de área y 2,50m de lado.\n- Para tres personas: 16m2 de área y 2,50m de lado.\nOficinas:\n- Locales individuales: 12m² de área y 3m de lado.\n- Unidades con más de 2 locales: uno de 9m² de área y 2.50m de lado; los restantes 7.50m² de área y 2.50m de lado.\nEdificios de actividades varias:\n- Locales comerciales y/o de trabajo, depósitos comerciales y/o industriales, vestuarios colectivos de clubes y/o asociaciones, gimnasios y demás locales de deportes, comedores colectivos, cocinas de hoteles, restaurantes, casas de comida, y todo otro local similar por analogía: 16m² de área y 3m de lado.\nEn todos los casos las dimensiones se calcularán de acuerdo a las siguientes normas:\n- Comedores colectivos: 0,90m2 por persona.\n- Cocinas (excluidas otras dependencias): 0,10m2 por persona.\n- Vestuarios colectivos: 0,50m2 por persona.\n- Cocinas: Dimensiones: 3m2 de área y 1,30m de lado.\nBaños y retretes: Las dimensiones de estos locales se fijan en función del número de artefactos a instalar en los mismos:\n- Bañera, inodoro, bidet y lavabo: 3,00 m² / 1,20 m de lado.\n- Ducha, inodoro, bidet y lavabo: 2,60 m² / 1,10 m.\n- Ducha, inodoro y lavabo: 1,50 m² / 1,00 m.\n- Ducha e inodoro: 1,20 m² / 0,80 m.\n- Ducha: 0,70 m² / 0,80 m.\n- Inodoro: 0,90 m² / 0,80 m.\nLas superficies consideradas son mínimas, libres y netas con exclusión de muros con revestimientos, armarios, botiquines, etc.",
30:"Servicio mínimo de salubridad: En todo predio edificado existirán por lo menos los siguientes servicios de salubridad:\n- Un retrete de mampostería u hormigón con solado impermeable, dotado de inodoro.\n- Una pileta de lavar.\n- Una ducha o bañera con sus desagües.\n- Digestor y pozo absorbente calzado y demás exigencias que imponga el reglamento particular o el Departamento Provincial de Aguas y/o ARSA.",
31:"En locales o edificios públicos, comerciales e industriales: En todo edificio público, comercial, industrial o local destinado a estos fines se dispondrá de locales de servicios de salubridad de acuerdo al siguiente criterio y sin perjuicio de lo que establezcan las reglamentaciones de los organismos pertinentes:\n- Menos de 5 personas: 1 inodoro y 1 lavabo c/canilla.\n- Más de 5 personas: habrá servicios separados por sexo, en la siguiente proporción:\nHOMBRES: Hasta 10: 1 inodoro y 1 mingitorio. Hasta 20: 1 inodoro y 1 mingitorio. Hasta 40: 2 inodoros y 2 mingitorios. Más de 40: 1 inodoro, 1 mingitorio por cada 30 hombres o fracción. Lavabos: hasta 60, 1 lavabo c/20 personas; más de 60, 1 lavabo c/20 personas o fracción.\nMUJERES: Hasta 30: 2 inodoros. Más de 30: 1 inodoro por c/20 personas adicionales. Lavabos: hasta 60, 1 lavabo c/10 personas; más de 60, 1 lavabo c/20 personas o fracción.",
32:"En todos los edificios a construir, los locales deberán tener las alturas mínimas indicadas en la planilla Anexo I.",
33:"En los edificios destinados a uso público el Organismo de Aplicación podrá exigir alturas mayores a las previstas.",
34:"Todo local podrá tener entrepisos o niveles intermedios de altura menor a la establecida, siempre que cumpla con las siguientes condiciones:\n• El entrepiso y la parte que cubre deberá tener una altura mínima de paso de 2,20m en cada uno, libre de vigas, espesor de losa, etc.\n• La superficie del entrepiso no cubrirá más de la mitad del área del local.\nSe deberá tener una completa continuidad espacial entre los ambientes, pudiendo cerrarse los locales sólo parcialmente.",
35:"Los locales que por desniveles de su cielorraso o piso tengan una altura uniforme en toda su superficie deberán cumplir con los siguientes requisitos:\n• La altura media obtenida dividiendo el volumen por la superficie del local será igual a la altura mínima establecida.\n• La altura en el punto más bajo no podrá ser inferior a 2,20m.",
36:"Los vanos para iluminación de locales estarán cerrados por puertas vidrieras, ventanas, banderolas, ladrillos de vidrio o cualquier otro elemento traslúcido que permite la trasmisión efectiva de luz desde el exterior.",
37:"La ventilación se obtendrá haciendo que parte o la totalidad de estos vanos puedan abrirse, de tal forma que permitan obtener las condiciones de ventilación requeridas.",
38:"Queda prohibido ubicar vanos para iluminación y/o ventilación en muros divisorios de predios. (Medianeras).",
39:"La superficie de los vanos para iluminación y ventilación, estará supeditada al destino, superficie, forma y altura del local teniendo en cuenta que:\nI: Área de iluminación.\nV: Área de ventilación.\nS: Área del local.",
40:"En lo referente a iluminación y ventilación, deberán cumplimentarse las siguientes condiciones, según los casos que a continuación se detallan:\n1- Iluminación y ventilación con vano directamente al exterior: I: S/10 — V: I/2.\n2- Iluminación y ventilación con vano al exterior bajo parte cubierta: I: S/6 — V: I/2.\n3- Ventilación e iluminación vertical o cenital: I: S/15 — V: I/2. Valor mínimo de “V”: 0,25m2. En el caso de escaleras “S”, será la sumatoria del área de la caja de todos los pisos.\n4- Ventilación por medios mecánicos: Los locales de salubridad en lugares de espectáculos y diversión públicos, tendrán además de la ventilación exigida, ventilación mecánica que asegure una renovación de aire de diez veces el volumen del local por hora, mediante dos equipos, uno en uso y el otro auxiliar. El funcionamiento de estos equipos será obligatorio en horas de función y se colocará una luz piloto que indique su funcionamiento.\n5- Ventilación de baños o cocinas ubicadas en planta baja: Cuando un local de baño o cocina esté ubicado en planta baja y su ventilación se haga a la vía pública, tendrá la boca de salida de ventilación a 2,00m encima del nivel de vereda como mínimo. Se exceptúan de esta disposición las edificaciones retiradas de la L.M.\n6- Ventilación e iluminación de locales de comercio o pasajes: El pasaje se considerará como vía pública, debiendo los locales cumplir con las condiciones exigidas para locales de comercio, pero además tendrán una ventilación auxiliar obligatoria que cumplan con las condiciones 3 u 8 ubicadas en el lado opuesto del vano sobre el pasaje.\n7- Ventilación por tubos independientes:\n- Cumplirán las siguientes condiciones (S sup. local): Sección transversal mínima: S/400. Sección mínima de tubo: 0,03m2.\n- El conducto será vertical o inclinado en no más de 45º.\n- La abertura que ponga en comunicación al local con el conducto será regulable y de área no inferior al conducto.\n- Los tramos horizontales del conducto no podrán superar el ¼ de la altura propia del mismo.\n- El remate del tubo en azotea se hará a los 4 vientos con “sombrerete”, y la altura del mismo deberá estar a 1,50m sobre el nivel de cualquier solado o coronamiento de muro.\n8- Ventilación por tubos comunes:\n- El conducto será para unificar dos o más tubos independientes.\n- Será de mampostería, hormigón y dentro de su sección no se ubicarán desagües o cañerías.\n- Su sección no será inferior a 0,60m2 y la relación de sus lados no mayor de 1/3.\n- Los tramos horizontales no podrán superar el ¼ de la altura propia del conducto.\n- El conducto de cada local rematará en el conducto común con un recorrido vertical mínimo de 1,00m y la diferencia de nivel de salida será como mínimo de 0,50m.\n- El conducto será vertical o inclinado en no más de 45º.\n- El remate del conducto en azotea se hará a los 4 vientos con “sombrerete” y la altura del mismo deberá estar a 1,50m sobre el nivel de cualquier solado o coronamiento de muro.",
41:"En tabla se indica las condiciones de iluminación y ventilación exigidas para cada local. La condición consignada en tabla es optativa, pudiendo tomarse para cumplir la ventilación o iluminación cualquiera de las mismas.\nCuando el número correspondiente a la condición se encuentra cerrado entre paréntesis, se interpretará que dicho local debe cumplir con cualquiera de las otras condiciones de iluminación y ventilación consignadas en la tabla.",
42:"La determinación del destino de cada local será la que lógicamente resulte de su ubicación y dimensiones y no la que arbitrariamente pudiera ser consignada en los planos.\nEl Organismo de Aplicación, presumirá el destino de los locales de acuerdo a su criterio, pudiendo rechazar proyectos de plantas cuyos locales acusan intención de una división futura.",
43:"Con el fin de preservar las condiciones acústicas de los locales, evitándose la propagación por vía sólida o aérea de ruidos o vibraciones, deberán cumplimentarse las siguientes normas:\nLos tabiques o muros divisorios entre diversas unidades habitables se deberán construir según algunos de los siguientes sistemas constructivos:\n- Tabique de ladrillos macizos (comunes o prensados) de 0,15m de espesor revocado a la cal o en yeso por ambos paramentos.\n- Tabique de bloques de hormigón hueco de 0,20m de espesor, revocado por ambos paramentos en cal o yeso.\n- Doble tabique de ladrillos macizos (comunes o prensados) dejando entre ellos un espacio de 0,075m no colocando ninguna conexión que una estos tabiques entre sí (ladrillos, varillas, zunchos) y revocando los paramentos por ambos lados.\n- Doble tabique de bloques de hormigón hueco de 0,10m de espesor sin conexión alguna entre ambos tabiques y revocados a la cal o yeso por ambos paramentos.\n- Tabiques de hormigón armado macizo (2.400 kg/m3) de 0,10m de espesor.\n- Tabique de bloques cerámicos huecos de 0,08m de espesor revocados en ambos paramentos en cal y/o yeso.\n- Sistemas constructivos prefabricados que cuenten con Certificado de Aptitud Técnica de la Secretaría de Desarrollo Urbano y Vivienda actualizada.\nLas puertas de acceso a unidades de vivienda deberán ser macizas y de contacto perfecto en sus cuatro lados. Se exceptúan los accesos que tengan doble puerta común (tal como pasillos de accesos, zaguanes y hall de entrada).\nLos entrepisos que separan distintas unidades habitables, deberán cumplir lo siguiente: La losa del contrapiso deberá asegurar una aislación por vía aérea por lo menos igual a la exigida para muros y tabiques divisorios o sea, tratarse de una losa de hormigón armado de 0,10m de espesor o equivalente desde el punto de vista acústico, con contrapiso de 0,07m.",
44:"Cuando determinadas instalaciones, tales como moteles, ascensores, tuberías que conecten bombas de fluidos, aparatos climáticos y/o sanitarios, canchas de pelota, bochas o similares, sean susceptibles de producir vibraciones o ruidos, deberán tomarse las precauciones que aseguren que no se transmitan por vía sólida o aérea a otros ambientes del mismo edificio o a otros edificios.",
45:"A los fines de aislar adecuadamente a los edificios de humedades transmitidas por el terreno, instalaciones, agentes atmosféricos y otras fuentes, deberán cumplimentarse las siguientes normas:\n- Es obligatoria la ejecución de contrapiso con aislación hidrófuga, sobre el terreno, para colocar los pisos, debiendo ejecutarse con anterioridad a los trabajos de limpieza del suelo, eliminación de tierra negra o materia orgánica, y consolidación de ésta.\n- Todos los muros de una construcción en contacto con el terreno, ya sean internos o externos, cualquiera sea su espesor, deberán presentar una doble capa aisladora (horizontal y vertical), que se ajustará con material hidrófugo, estará situada más arriba del nivel del solado y se unirá al contrapiso.\n- En los locales ubicados total o parcialmente bajo el nivel del terreno, se deberá construir en la parte externa del paramento debajo del nivel de aquel, un tabique de ladrillo de panderete y, en casos de mucha profundidad, de hormigón, apoyando el terreno natural y terminado con aplicación de revoque hidrófugo que se unificará con la capa aisladora horizontal.\n- Todos los locales que contengan instalaciones sanitarias (cocinas, baños, etc.) deberán tener pisos y paredes impermeables en las proximidades de las bocas de salidas de líquido y hasta una altura de 1,50m.\n- No podrán arrimarse canteros a muros separativos de viviendas si no se prevé un aislamiento hidrófugo vertical.\n- Los desagües cumplirán con las reglamentaciones del D.P.A.\n- Los muros exteriores deberán contar con aislación hidrófuga permanente.",
46:"Todo edificio con más de dos (2) unidades independientes y/o destinado a concentraciones de público (cubierto o descubierto) deberá asegurar la rápida evacuación del mismo de acuerdo a las condiciones mínimas que se establecen seguidamente. En los medios de egreso deberán respetarse los siguientes criterios en cuanto a su dimensionamiento:\n1) El ancho mínimo de puertas de toda unidad independiente que dé a pasajes, corredores comunes o públicos será de 0,90m libres hasta 50 personas o fracción; y la altura mínima no podrá ser inferior a 2,00m. En caso de escaleras, las puertas abrirán sobre un descanso.\n2) En lugares destinados a la concentración de público (cubierto o descubierto) el ancho libre total de las puertas de egreso se calculará a razón de 0,01m por persona, no pudiendo ser nunca inferior a 1,50m.\n3) El ancho libre de los pasajes, corredores o similares que conectan con la vía pública se calculará como en el inciso 2) no pudiendo ser nunca inferior a 1,20m.\n4) En el caso de pasajes comerciales de uso público el ancho libre mínimo será de 3,00m.\n5) El ancho libre de las escaleras no podrá ser inferior a 0,90m. El ancho de huella mínima se fija en 0,26m y la alzada máxima en 0,18m; siendo la altura máxima a salvar sin descanso de 3,00m. Cuando la escalera sea de tramos curvos, el ancho de huella mínima (0,26m) se tomará en el centro de giro para el caso de ancho de escaleras iguales o menores que 0,90m y a 0,45m del limón inferior cuando el ancho sea mayor, no pudiendo en ningún punto del recorrido a 0,10m.\n6) En lugares destinados a concentración de público, el ancho de las escaleras se calculará de acuerdo a lo expresado en el inciso 2).\n7) Las distancias máximas entre circulaciones verticales según el destino de la edificación serán de: Destinados a concentración de público: edificios comerciales, industriales o depósitos: 45 m. Usos residenciales, instituciones o semejantes: 30m.\n8) Las escaleras que no sirvan de medio de egreso o acceso obligado a viviendas o edificios de concentración de público, tendrán un ancho mínimo de 0,70m; siendo el ancho de huella mínimo de 0,23m y la alzada máxima de 0,20m.",
47:"Todas las escaleras tendrán barandas o pasamanos rígidos por lo menos en uno de sus lados salvo que su ancho supere 1,40m en cuyo caso se colocarán en ambos lados.",
48:"Las escaleras reglamentarias deberán ejecutarse con materiales incombustibles.",
49:"Las rampas se considerarán como medios de egreso siempre que por su ubicación, construcción y ancho respondan a lo establecido en los artículos anteriores; y la pendiente máxima será del 12 %. Su solado antideslizante.",
50:"No se computarán como aberturas de salidas las que correspondan a puertas vaivén; las puertas giratorias se considerarán como aberturas de salida en edificios residenciales y de oficinas en hasta un 50% del ancho de cálculo exigido. Su diámetro mínimo se fija en 1,65m. El 50% restante se cubrirá obligatoriamente con puertas de abrir.",
51:"En toda edificación, sin perjuicio del cumplimiento de otras reglas del arte, deberán cumplimentarse las reglas básicas de seguridad establecidas en el Reglamento Técnico de Estructuras.\nLas estructuras de HºAº cumplimentarán las reglas del Reglamento Técnico PRAEH.",
52:"La elección del procedimiento de cálculo será libre. En caso de usarse fórmulas nuevas se hará constar su procedencia y justificación, las que deberán contar con la aprobación del Organismo de Aplicación.\nSe exigirá por lo menos la exactitud que resulte del empleo de una regla de cálculo de 0,25m de longitud, o un procedimiento gráfico equivalente.",
53:"La estructura resistente deberá proyectarse y ejecutarse dentro de los límites del predio.\nUn muro divisorio con su cimiento podrá asentarse en ambos predios colindantes.\nLos muros privativos contiguos a predios linderos, sean o no resistentes deberán proyectarse y ejecutarse dentro del propio predio.",
54:"Los muros, según tipo, deberán ser construidos respetando los siguientes espesores mínimos:\nMuros portantes: ladrillos comunes 0,30m / ladrillos huecos y bloques de cemento: 0,20m.\nSe permitirán muros portantes de 0,15m de espesor cuando la pared no tenga más de 3,00m de altura y esté previsto de un encadenamiento de HºAº en su parte superior.\nLos muros medianeros se ejecutarán en todos los casos de ladrillos comunes y espesores mínimos de 0,30m y se materializarán a eje divisorio.",
55:"Los techos y azoteas transitables deberán estar cercados con barandas o parapetos de una altura de 1,00m computada desde el solado.",
56:"La cubierta de un techo, azotea o terraza sobre locales habitables será ejecutada con material impermeable, imputrescible y mal conductor térmico como ser: teja, pizarra, fibrocemento u otro material con sistema constructivo de aislación térmica equivalente.\nLa cubierta de locales que no sean habitables se ejecutará con material impermeable e incombustible.",
57:"En todos los techos y azoteas por cada 80,00m2 de superficie, deberá colocarse un caño de 4” de diámetro interno. Dicho caño podrá ser puesto en comunicación directa con la calle o a red de evacuación pluvial por medio de caños de material adecuado, colocado a nivel de la calzada y con pendiente necesaria para asegurar el perfecto escurrimiento de las aguas.",
58:"Los techos que desagüen con caída libre no podrán hacerlo sobre predios linderos, ni sobre la vía pública (vereda).",
59:"Los cimientos de los muros de los sótanos tendrán que ajustarse a lo dispuesto en el Art. 53.",
60:"El espesor de los muros envolventes en sótanos tendrá que tener en cuenta condiciones estructurales y de aislación hidrófuga.",
61:"Todos los sistemas no tradicionales, deberán contar con Certificado de Aptitud Técnica, expedido por la Secretaría de Estado de Desarrollo Urbano y Vivienda actualizado al momento de realización de la obra.",
62:"Las instalaciones técnicas complementarias deberán ser ejecutadas de acuerdo a las normas que a continuación se establecen:\n- Las instalaciones sanitarias deberán cumplir las normas establecidas por el Departamento Provincial de Aguas.\n- Las instalaciones eléctricas en sus aspectos generales, deberán respetar las normas dictadas por Agua y Energía Eléctrica de la Nación. Los locales para medidores deberán ser de fácil acceso y contar con buena ventilación e impermeabilización. Los medidores deberán ser de fácil acceso y contar con buena ventilación e impermeabilización y no deberán estar comunicados con locales que tengan instalaciones de gas. En caso de baterías, la fila inferior de medidores no deberá distar menos de 0,90m del solado y la superior no más de 1,80m. Al frente de los medidores deberá quedar un espacio de 1,00m de ancho libre como mínimo.\n- Las instalaciones de gas, deberán cumplir las normas establecidas por Gas del Estado.",
63:"Los locales para calderas, incineradores y otros aparatos térmicos, deberán cumplir los siguientes requisitos:\n- Se dejará un paso mínimo de 0,60m alrededor del perímetro de cada aparato.\n- Contarán con una altura mínima de 1,00m sobre maquinaria y la altura mínima de los locales será de 2,50m.\n- No deberán tener conexión con los locales para medidores de gas ni contenerlos.",
64:"Los conductos de aire acondicionado, deberán aislarse convenientemente y no podrán alojar otros conductos.",
65:"Los pozos absorbentes y cámaras sépticas deberán construirse totalmente dentro del predio y retirados de toda edificación y de los ejes divisorios de la propiedad a 1,50 m como mínimo. Los pozos deberán calzarse hasta 2,50m de profundidad y cubrirse con losa de HºAº o bóveda de mampostería de ladrillos y mezcla de arena, cal y cemento, y contar con un caño de ventilación que arranque de la parte más alta de dicha bóveda y ventilada a los 4 vientos; también deberán tener su correspondiente cámara séptica. En todos los casos, la instalación deberá prever la posibilidad de conexión futura a la red cloacal.",
66:"La cota de la planta baja se efectuará de forma tal que quede asegurado el desagüe pluvial a la vía pública y el cloacal a la red (si hubiera). En los casos en que no exista proyecto de nivelación y no se pueda fijar nivel de vereda la Municipalidad exigirá como nivel cero (0) de planta baja la cota 0,50m con respecto al eje de la vía de acceso.",
67:"Queda prohibido lanzar a la vía pública, terrenos propios y vecinos y a los cursos de agua, los líquidos cloacales y las aguas servidas.",
68:"Para la construcción de panteones, sepulturas o monumentos, regirá para las mismas lo dispuesto en este Código para la edificación en general, en cuanto sea pertinente.",
69:"La Municipalidad de Viedma podrá en el futuro y de acuerdo a su criterio dictar ordenanzas especiales referentes a este tema.",
70:"Los edificios de uso comercial o las viviendas colectivas en altura quedan sujetas a las disposiciones de prevención contra incendios que especifican la Ley Nº 19587 de Seguridad e Higiene en el Trabajo y su Decreto Reglamentario Nº 4100/73.",
71:"Es obligatoria la colocación en la acera de una valla provisoria en toda la extensión del frente de cualquier trabajo que por su índole, sea peligroso, incómodo o signifique un obstáculo para el tránsito en la vía pública. La valla provisoria se construirá de modo que impida la salida del material al exterior. En todos los casos las vallas dejarán un paso libre mínimo de 1,00m de ancho y una altura de 2,40m.",
72:"Las demoliciones deben ejecutarse de tal forma que se eviten, por todos los recursos posibles, perjudicar los edificios linderos y el tránsito en la vía pública. Para tal fin deberá ejecutarse un cerco protector provisorio en toda la extensión del frente cuya altura libre mínima será de 2,40m.",
73:"La demolición de los muros se hará paulatinamente y no por bloques y no podrán arrojar materiales desde una altura mayor de 4,00m.",
74:"El responsable de los trabajos de demolición deberá proceder al retiro de escombros y posterior limpieza de los materiales caídos en las fincas linderas o la vía pública.",
75:"Para los muros de 0,15 m o más de ancho, los cimientos tendrán como regla general, un ancho de 0,15 m mayor que el ancho de los muros que soportan; los tabiques de ancho no mayor de 0,10 m podrán apoyar directamente sobre contrapiso.",
76:"En los casos en que se proyecten estructuras de hormigón armado, metálicas o similares en elevación, que superen las dos (2) plantas o en caso de no tenerse conocimiento preciso de las características de resistencia del suelo, el Organismo de Aplicación podrá exigir la ejecución de un estudio de suelos a cargo de personal competente.",
77:"Todo propietario que desee efectuar cualquier tipo de edificación, modificación o demolición, deberá solicitar permiso por escrito a la Municipalidad en los formularios que para tal fin ésta le provea. En caso de que el Organismo de Aplicación lo considere necesario deberá presentar los títulos de propiedad.\nLa Municipalidad de Viedma se ajustará a lo establecido por Ordenanza 2027/86.",
78:"Con la solicitud de permiso se deberá adjuntar la siguiente documentación:\n- Memorias descriptivas de los materiales a emplear y de su aplicación.\n- Cuatro copias de los planos respetando las normas de presentación del Consejo Profesional de Ingeniería, Agrimensura y Arquitectura de Río Negro, al que se le agregará las especificaciones y ocupación del suelo del Código Urbano de Viedma.",
79:"En los planos se indicará:\n- Planta general del cuerpo del edificio y del terreno en escala 1:100.\n- Las secciones necesarias para dar una idea clara de las construcciones a realizar, como mínimo dos, en escala 1:100.\n- Vista de la fachada o fachadas en escala 1:100.\n- Croquis de ubicación de la propiedad.\nLos planos deberán indicar el destino de cada local y todas las medidas numéricas necesarias y especificaciones técnicas para su interpretación.\nLos planos deberán estar firmados por uno o más profesionales de la construcción en Proyecto y Dirección Técnica y visados por el correspondiente Consejo o Colegio Profesional; la firma del constructor por ejecución de obra será obligatoria en los casos contemplados en la Ord. 4009/01.",
80:"Los planos se presentarán en copias heliográficas, representándose con un perfil reforzado la parte edificada que queda subsistente, en relleno la que se proyecta realizar, con amarillo la que se demolerá, con marrón la que se construirá en madera, con azul la que se efectuará con acero o hierro y con verde la que se construirá en hormigón.",
81:"Los Entes Oficiales, ya sea provinciales o nacionales deberán tramitar su correspondiente permiso de construcción ante la Municipalidad de Viedma.",
82:"En las edificaciones donde la estructura resistente exige un estudio estático, deberá presentarse una planilla de cálculo conforme al modelo que proveerá el Organismo de Aplicación.",
83:"Los planos, planillas de cálculo y memorias descriptivas serán firmadas por el proyectista, calculista y conductor técnico matriculado en el Consejo Profesional de Ingeniería, Agrimensura y Arquitectura de la Provincia de Río Negro, como asimismo por el constructor que deberá estar inscripto en el Registro a que hace referencia el artículo Nº 93 y por el propietario del inmueble.",
84:"Todo plano que no se ajuste a lo establecido en el presente reglamento será devuelto al interesado para modificarlo o rehacerlo debiendo ser presentado de nuevo en un plazo no mayor de 60 días.",
85:"Una vez abonados los derechos correspondientes y aprobada toda la documentación, se entregará al interesado las copias aprobadas de la misma selladas con el correspondiente número de permiso de construcción.",
86:"No podrá iniciarse ninguna obra sin contar con el permiso correspondiente.\nDeberá encontrarse en la obra a disposición de los inspectores y hasta la terminación de la misma, una copia de la documentación visada al igual que cualquier planilla de autorización entregada por el municipio.",
87:"Se considerará caduco todo permiso de edificación correspondiente a obras que no se hayan comenzado dentro del plazo de seis meses a contar desde la fecha de pago de los derechos, pasado el cual deberá solicitarse nuevamente el permiso y abonar por segunda vez los derechos.",
88:"El propietario de la obra o el constructor de la misma, no podrá introducir modificaciones que alteren los planos aprobados o ampliaciones que aumenten la superficie cubierta y el valor de la propiedad, sin previo permiso que se solicitará presentando la modificación.",
89:"Si una obra estuviera suspendida en su ejecución durante seis meses y no se hubieran notificado por escrito las razones de dicha suspensión a la Municipalidad la misma solicitará, dejando constancia del estado en que se encuentran los trabajos y previa inspección, mandar archivar el expediente debiendo el propietario en tal caso obtener un nuevo permiso para su continuación.",
90:"En caso que se notificare por escrito a la Municipalidad de la suspensión de obra, la misma podrá prorrogar la vigencia del permiso en plazo que quedará a su criterio y no podrá ser inferior a seis meses.",
91:"Si durante la ejecución de una obra el propietario deseara cambiar de conductor técnico, podrá hacerlo mediante una solicitud firmada por él, por el nuevo conductor técnico y el conductor técnico saliente, que se presentará a la Municipalidad para su conocimiento.\nLa documentación de la obra deberá ser firmada por el nuevo Director Técnico y visada por el Colegio o Consejo correspondiente.",
92:"Es obligatoria la colocación al frente de la obra, en lugar visible, de un letrero mínimo de 0,40m x 0,60m, cuyo texto se ajustará a lo establecido en la Ley Nº 442 y su Decreto Reglamentario Nº 120/74.",
93:"Los constructores de las distintas categorías deberán registrar su firma y domicilio en un libro especial que llevará el Organismo de Aplicación.",
94:"Todo constructor deberá comunicar su cambio de domicilio al Organismo de Aplicación dentro de los ocho días de producido.",
95:"Los constructores serán responsables ante la Municipalidad de todo lo que pudiera ocurrir en la ejecución de cualquier tipo de edificación y del fiel cumplimiento de las disposiciones establecidas en el presente Código, y de las normas que al respecto establece la Ley Nº 442.",
96:"El Organismo de Aplicación podrá efectuar las inspecciones en el momento que considere necesario y verificará el cumplimiento de las normas establecidas.",
97:"Dentro de los quince días de terminada cualquier obra de edificación que exija la presentación de planos, deberá solicitarse al Organismo de Aplicación la inspección de la misma, que se hará en formularios especiales firmados por el propietario y el conductor técnico.",
98:"Los responsables (propietario y/o director técnico o constructor) de que se realicen edificaciones nuevas, modificaciones, complementaciones, refacciones o demoliciones de las existentes, sin el correspondiente permiso municipal, serán pasibles de la aplicación de una multa de (1/5 a 1/2) del sueldo mínimo municipal hasta que regularicen el trámite pertinente.",
99:"Los responsables (propietario y/o director técnico o constructor) de que se realicen obras en violación de lo previsto en el Art. 88 de este Código, serán pasibles de la aplicación de una multa diaria de (1/5 a un sueldo) mínimo municipal hasta que regularicen el trámite respectivo.",
100:"Los constructores que autoricen habilitar las obras por ellos realizadas sin haber obtenido el certificado de inspección final a que hace referencia el artículo 97 se harán pasibles de la aplicación de una multa diaria de ¼ de sueldo mínimo municipal.",
101:"La Municipalidad de Viedma podrá disponer la inhabilitación de la firma de los constructores y/o directores técnicos que suscriben los planos y memorias descriptivas de cualquier clase de edificación en los casos siguientes y comunicando en cada caso al Consejo Profesional de Ingeniería, Agrimensura y Arquitectura de la Provincia de Río Negro:\n- Cuando en repetidas ocasiones, sean responsables de infracciones a este Código.\n- Cuando se haya ordenado la suspensión de una obra y la continúa desacatando la orden.\n- Cuando no vigile directamente o por medio de su capataz o encargado la ejecución de la misma.\nLa inhabilitación por suspensión de firma será ejecutada, la primera vez, por un período de tres meses, la segunda por seis meses y la tercera por un año.\nEn caso de nueva reincidencia se dispondrá la inhabilitación permanente.",
102:"Cuando efectuaren obras en violación a las disposiciones de este Código los responsables titular y representante técnico se hará pasible de la aplicación de una multa de 10 (diez) sueldos mínimo municipal a 20 (veinte) sueldos mínimos municipales, según la gravedad de la infracción. Sin perjuicio de lo antes previsto el Organismo de Aplicación ordenará la modificación y/o demolición de lo construido en infracción dentro del plazo que determine, el que no será mayor de ciento veinte días corridos. Vencido el plazo ordenado sin que se hubieran ejecutado las obras de modificación y/o demolición pertinente, se aplicará a los responsables una multa de 40 (cuarenta) sueldos mínimos municipales y se dispondrá la ejecución por parte de la Municipalidad a cargo de los mismos de las obras de demolición que fueren necesarias para hacer cesar la situación infraccional.",
103:"Cuando el peligro de derrumbe de una pared o edificio apareciera como inminente la Municipalidad de Viedma podrá disponer su demolición sin más trámite, por sus propios organismos, a cargo del propietario responsable, debiendo tan solo levantarse acta en el momento de efectuarse la demolición.",
104:"Deróganse todas las disposiciones municipales que se opongan al presente Código.",
105:"La Municipalidad de Viedma reglamentará en forma integral este Código, pudiendo incorporar otras normas que surjan de su actualización, consultando para tal caso a la Subsecretaría de Vivienda y Desarrollo Urbano de la Provincia de Río Negro.",
106:"Los trámites iniciados en la Municipalidad con fecha anterior a la vigencia de este Código, no mayor de seis meses, deberán ser resueltos por la Municipalidad conforme a las normas vigentes en la época en que se hubieran efectuado las presentaciones respectivas ante ella."
},
build(add){

// Art. 1
add(1,"Regla","¿Cuál es el objeto del Código de Edificación de Viedma?","Regular la <strong>realización de obras de edificación</strong>.");
add(1,"Dato","¿Qué cuatro tipos de obras de edificación regula el Código?","<ul><li>Construcción</li><li>Modificación</li><li>Refacción</li><li>Demolición</li></ul>(“y/o”: pueden darse juntas o separadas)");
add(1,"Dato","En el Código, ¿qué dos variantes comprende la “modificación” de una obra?","<strong>Ampliación</strong> o <strong>alteración</strong>.");
add(1,"Caso","Un propietario sólo quiere demoler un galpón, sin construir nada. ¿Por qué la demolición queda alcanzada por el Código?","Porque la <strong>demolición</strong> es una de las obras de edificación que el Código regula.");
// Art. 2
add(2,"Regla","¿Cuál es el ámbito territorial de aplicación del Código?","El <strong>municipio de Viedma</strong>.");
add(2,"Dato","¿Qué ley provincial base establece cómo se pone en vigencia el Código?","La <strong>Ley Nº 929</strong>.");
add(2,"Dato","¿Qué leyes modificatorias de la Ley 929 se citan para la puesta en vigencia del Código?","Leyes <strong>Nº 1373, Nº 1440 y Nº 1553</strong>.");
add(2,"Dato","¿Qué decreto reglamentario se cita para la puesta en vigencia del Código?","El <strong>Decreto Reglamentario Nº 492/82</strong>.");
add(2,"Regla","Si las leyes y el decreto citados para la vigencia del Código fueran modificados o sustituidos, ¿qué normas se aplican?","Se aplican <strong>las que las modifiquen o sustituyan</strong> (remisión dinámica).");
// Art. 3
add(3,"Regla","¿Quién es el Organismo de Aplicación del Código?","La <strong>Municipalidad de Viedma</strong>, a través de sus <strong>oficinas competentes</strong>.");
add(3,"Facultad","¿Qué le corresponde exigir al Organismo de Aplicación?","El <strong>cumplimiento de los objetivos y normas</strong> del Código.");
add(3,"Facultad","¿Mediante qué instrumento el Organismo de Aplicación hace cumplir el Código?","<strong>Sancionando las reglamentaciones</strong> que considere necesarias.");
// Art. 4 — Definiciones
const DEF=[
["Acera","Espacio de la calle entre la <strong>Línea Municipal y la calzada</strong>, destinado al <strong>tránsito de peatones</strong>."],
["Alero","Plano horizontal <strong>no accesible</strong> destinado <strong>exclusivamente</strong> para resguardo de vanos y muros."],
["Balcón","Elemento <strong>accesible y transitable</strong>, voladizo o no, generalmente prolongación del entrepiso y limitado por un <strong>parapeto o baranda</strong>."],
["Calle","Banda vial de <strong>dominio público</strong> delimitada <strong>entre líneas municipales</strong>."],
["Conducto","Espacio dispuesto para <strong>contener tuberías</strong>, o <strong>conducir o evacuar</strong> aire, gases, líquidos o sólidos."],
["Calzada","Espacio de calle <strong>entre aceras enfrentadas</strong>, destinado al <strong>tránsito de vehículos</strong>."],
["Eje divisorio","Delimitación <strong>entre parcelas de dominio privado</strong>."],
["Entrepiso","<strong>Estructura resistente horizontal</strong>."],
["Estructura","Armazón o esqueleto y <strong>todo elemento resistente</strong> de un edificio."],
["Línea Municipal (L.M.)","Delimitación entre el <strong>dominio público municipal</strong> y el <strong>dominio privado</strong>."],
["Local","Cada una de las <strong>partes cubiertas cerradas</strong> en que se divide un edificio."],
["Local habitable","El destinado a <strong>habitación, morada, trabajo o permanencia continuada de personas</strong> (con exclusiones)."],
["Marquesina","<strong>Alero</strong> que avanza <strong>sobre un acceso</strong>, generalmente ubicado sobre la vía pública."],
["Muro","Cerramiento vertical <strong>apto para soportar cargas</strong>."],
["Piso","Espacio comprendido entre el nivel de un <strong>solado</strong> y el nivel del <strong>techo siguiente</strong> sobrepuesto."],
["Solado","<strong>Revestimiento</strong> del suelo natural o de un entrepiso."],
["Sótano","<strong>Piso</strong> situado <strong>bajo el nivel del suelo</strong>."],
["Tabique","Cerramiento vertical <strong>no portante</strong>."]
];
DEF.forEach(([t,d])=>add(4,"Definición",`Definí: <em>${t}</em>`,d));
add(4,"Excepción","¿Qué locales quedan <em>excluidos</em> de la definición de “local habitable”?","<ul><li>Lavaderos</li><li>Cuartos de baño</li><li>Despensas</li><li>Pasajes</li><li>Vestíbulos</li><li>Depósitos</li><li>o similares</li></ul>");
add(4,"Caso","Un estudio donde una persona trabaja todo el día: ¿qué lo encuadra como local habitable?","El <strong>trabajo</strong> y la <strong>permanencia continuada</strong> de personas.");
add(4,"Distinción","Muro vs. tabique: ¿cuál es la diferencia?","Ambos son cerramientos verticales; el <strong>muro soporta cargas</strong>, el <strong>tabique no es portante</strong>.");
add(4,"Distinción","Alero vs. balcón: ¿cuál es la diferencia clave?","El alero es <strong>no accesible</strong> (sólo resguardo de vanos y muros); el balcón es <strong>accesible y transitable</strong>, con parapeto o baranda.");
add(4,"Distinción","Acera vs. calzada: ¿qué separa a cada una y a quién está destinada?","Acera: entre L.M. y calzada, para <strong>peatones</strong>. Calzada: entre aceras enfrentadas, para <strong>vehículos</strong>.");
add(4,"Distinción","Línea Municipal vs. eje divisorio: ¿qué separa cada una?","L.M.: dominio <strong>público municipal</strong> / dominio privado. Eje divisorio: entre <strong>parcelas privadas</strong>.");
add(4,"Distinción","¿Qué relación hay entre marquesina y alero?","La marquesina <strong>es un tipo de alero</strong>: el que avanza sobre un acceso, generalmente sobre la vía pública.");
add(4,"Distinción","¿Qué relación hay entre sótano y piso?","El sótano <strong>es un piso</strong>: el situado bajo el nivel del suelo.");
// Art. 5
add(5,"Regla","¿Conforme a qué norma se considera zonificada Viedma a los fines de este Código?","Conforme a las disposiciones del <strong>Código Urbanístico</strong> respectivo.");
// Art. 6
add(6,"Regla","Los reglamentos técnicos de fundaciones, estructuras, instalaciones, etc., ¿qué carácter tienen respecto del Código?","<strong>Forman parte</strong> del Código de Edificación.");
add(6,"Dato","¿Cuántos reglamentos técnicos forman parte del Código?","<strong>Once (11)</strong>.");
add(6,"Dato","¿Qué cuatro reglamentos se toman del Código de Edificación de la Ciudad de Buenos Aires?","<ul><li>Fundaciones</li><li>Estructuras</li><li>Instalaciones Eléctricas</li><li>Ascensores y Transportadores</li></ul>","1,2,4,8");
add(6,"Dato","¿Qué reglamento rige las estructuras de hormigón?","El <strong>PRAEH</strong>: Proyecto de Reglamento Argentino para Estructuras de Hormigón.","3");
add(6,"Dato","¿Qué reglamento rige lo sanitario (agua y cloacas)?","El <strong>Reglamento de O.S.N.</strong> o las normas que especifique el <strong>Departamento Provincial de Aguas</strong>.","5");
add(6,"Dato","¿Qué reglamentos rigen las instalaciones de gas y de energía?","<strong>Gas del Estado</strong> y <strong>Agua y Energía de la Nación</strong>.","6,7");
add(6,"Dato","¿Qué normas del SEDUV integran el Código?","Normas mínimas de <strong>Habitabilidad</strong> y normas mínimas de <strong>Habitabilidad Higrotérmica</strong>.","9,10");
add(6,"Dato","¿Qué normas aplican a hoteles, moteles, residenciales y hosterías?","Las Normas de Edificación de la <strong>Secretaría de Estado y Turismo de la Nación</strong>.","11");
// Art. 7
add(7,"Regla","¿Qué carácter deben tener las obras destinadas a habitación?","<strong>Permanente</strong>.");
// Art. 8
add(8,"Condición","¿Qué dos requisitos deben cumplir las obras de carácter transitorio?","1) <strong>Justificar su finalidad</strong>.<br>2) Contar con <strong>autorización expresa</strong> de la Municipalidad.");
add(8,"Facultad","En una obra transitoria, ¿qué puede exigir la Municipalidad además de autorizarla?","Las <strong>condiciones mínimas de habitabilidad y saneamiento</strong> que considere necesarias.");
add(8,"Caso","Un obrador temporario cuenta sólo con autorización tácita (nadie objetó). ¿Qué le falta para cumplir las exigencias de las obras transitorias?","<strong>Autorización expresa</strong> de la Municipalidad, además de <strong>justificar su finalidad</strong>.");
// Art. 9
add(9,"Prohibición","¿Qué dos tipos de construcciones prohíbe el Código?","Las de <strong>carácter precario</strong> y las hechas de <strong>adobe</strong>.");
add(9,"Caso","¿Qué impide autorizar una vivienda de adobe como obra de carácter transitorio?","El Art. 9, que <strong>prohíbe en forma absoluta</strong> las construcciones de adobe y las precarias.");
// Art. 10
add(10,"Regla","En materia de ocupación, ¿qué factores deben cumplir todas las edificaciones y según qué norma?","Los <strong>factores de edificación y de ocupación</strong> previstos por el Código Urbanístico.");
add(10,"Condición","¿Según qué criterio varían los factores de edificación y ocupación aplicables?","<strong>Según la zona</strong> de que se trate.");
// Art. 11
add(11,"Prohibición","¿Hasta qué altura la línea de edificación no puede avanzar sobre la Línea Municipal?","Hasta los <strong>2,70 m</strong> de altura.");
add(11,"Excepción","Por encima de 2,70 m, ¿qué salientes se permiten sobre la L.M.?","Salientes para <strong>balcones o locales</strong>.");
add(11,"Dato","Por encima de los 2,70 m, ¿cuánto pueden sobresalir las salientes para balcones o locales, medidas desde la L.M.?","Hasta <strong>1,00 m</strong>.");
add(11,"Dato","Las salientes sobre la L.M. para balcones o locales, ¿hasta qué distancia del eje divisorio pueden llegar?","Hasta <strong>0,15 m</strong> del eje divisorio (debe quedar a 0,15 m como mínimo).");
add(11,"Regla","En caso de ochava, ¿cómo debe disponerse la saliente de balcones o locales sobre la L.M.?","<strong>Paralela a la ochava</strong>.");
add(11,"Caso","Un balcón a 2,50 m de altura vuela 0,60 m sobre la vereda. ¿Qué regla incumple?","Hasta los <strong>2,70 m</strong> de altura no puede avanzarse sobre la L.M.");
// Art. 12
add(12,"Dato","¿Qué altura máxima pueden tener los cerramientos opacos en balcones?","<strong>0,90 m</strong>.");
add(12,"Dato","¿Desde dónde se mide la altura de los cerramientos opacos de balcones?","Desde el <strong>solado del balcón</strong>.");
// Art. 13
add(13,"Condición","¿Qué condición debe cumplir el balcón para admitir pantallas móviles?","Tener <strong>tres lados libres</strong>.");
add(13,"Dato","¿Qué tipo de pantallas se permiten en balcones con tres lados libres?","Pantallas <strong>móviles</strong>, <strong>traslúcidas, cribadas o similares</strong>, que produzcan cerramiento <strong>parcial</strong>.");
add(13,"Dato","En balcones con tres lados libres, ¿qué porcentaje máximo del perímetro libre pueden cerrar las pantallas móviles?","Como máximo el <strong>50 % del perímetro libre</strong>.");
add(13,"Caso","Balcón con dos lados libres: ¿qué requisito le falta para colocar pantallas móviles traslúcidas?","Tener <strong>tres lados libres</strong>.");
// Art. 14
add(14,"Dato","¿A qué altura mínima deben mantenerse aleros o marquesinas en planta baja?","Por encima de los <strong>2,40 m</strong>, medidos desde el <strong>nivel de vereda</strong>.");
add(14,"Dato","¿A qué distancia mínima del cordón debe quedar el borde exterior de aleros o marquesinas?","<strong>0,80 m</strong> como mínimo.");
add(14,"Excepción","¿Qué se permite en un retiro de frente de 4,00 m y dónde?","<strong>Toldo / pérgola</strong>, ubicado en el <strong>espacio de estacionamiento</strong>.");
add(14,"Dato","Sobre ejes medianeros, ¿qué altura máxima puede tener el muro divisorio dentro de la superficie de retiro?","<strong>0,60 m</strong>; por encima puede materializarse con <strong>rejas</strong>.");
add(14,"Condición","¿Qué se requiere para hacer un cerco verde de medianeras?","<strong>Acuerdo de vecinos por escrito</strong>.");
add(14,"Caso","Una marquesina a 2,60 m de altura cuyo borde queda a 0,50 m del cordón. ¿Qué medida incumple?","La distancia al cordón: el borde debe distar <strong>al menos 0,80 m</strong>. La altura cumple (más de 2,40 m).");
// Art. 15
add(15,"Facultad","¿Qué carácter tiene la exigencia municipal de cercar lotes baldíos?","<strong>Facultativo</strong>: la Municipalidad <strong>podrá exigirlo</strong>, en <strong>determinadas zonas</strong>, <strong>cuando lo considere conveniente</strong>.");
add(15,"Dato","¿Con qué materiales deben ejecutarse los cercos y muros divisorios de lotes baldíos?","Albañilería de <strong>ladrillos comunes</strong>, <strong>bloques huecos</strong> o <strong>piedra</strong>, o <strong>hormigón simple o armado</strong>.");
add(15,"Dato","¿Qué alturas mínima y máxima deben tener los cercos y muros divisorios de lotes baldíos?","Mínima <strong>2,00 m</strong> · máxima <strong>2,50 m</strong>.");
add(15,"Caso","Exigido el cerco de un lote baldío, el propietario hace un alambrado de 1,50 m. ¿Qué requisitos incumple?","El <strong>material</strong> (el alambre no está entre los admitidos) y la <strong>altura</strong> (mínimo 2,00 m).");
// Art. 16
add(16,"Regla","¿Qué se exige en toda nueva edificación respecto de sus fachadas?","Un <strong>adecuado tratamiento arquitectónico</strong> de las fachadas y de los muros divisorios visibles.");
add(16,"Condición","¿Qué muros divisorios alcanza el deber de tratamiento arquitectónico?","Los que <strong>queden a la vista desde la vía pública</strong>.");
// Art. 17
add(17,"Regla","¿Qué es obligatorio para las fachadas en la zona urbanizada?","Su <strong>revoque y pintado</strong>.");
add(17,"Excepción","¿Cuándo no es obligatorio revocar y pintar la fachada?","Cuando el <strong>estilo arquitectónico</strong> o la <strong>naturaleza del material</strong> se oponga (ej.: <strong>ladrillo a la vista</strong>, <strong>piedra laja</strong>).");
add(17,"Condición","Si una fachada no se revoca ni pinta por su estilo o material (ladrillo visto, piedra laja), ¿qué deben garantizar los materiales?","<strong>Proteger el muro de fachada contra los agentes atmosféricos</strong>.");
add(17,"Condición","¿En qué ámbito rige la obligación de revocar y pintar las fachadas?","En la <strong>zona urbanizada</strong>.");
// Art. 18
add(18,"Regla","¿Sobre qué vías es obligatorio construir aceras?","Sobre las vías <strong>pavimentadas o enripiadas</strong>.");
add(18,"Regla","¿Dónde se determinan las características generales de las aceras?","<strong>Reglamentariamente</strong>.");
add(18,"Facultad","¿Qué puede exigir el Organismo de Aplicación en casos especiales respecto de las aceras?","Un <strong>tratamiento diferenciado</strong> en entornos o sectores particulares de la ciudad, <strong>según proyecto particularizado</strong>.");
add(18,"Caso","Frente a una calle de tierra (ni pavimentada ni enripiada), ¿por qué no es obligatorio construir acera?","Porque esa obligación rige sobre vías <strong>pavimentadas o enripiadas</strong>.");
// Art. 19
add(19,"Regla","¿Con qué tipo de materiales deben construirse y terminarse las aceras?","Materiales <strong>antideslizantes</strong>.");
add(19,"Dato","¿Cuál es el ancho mínimo de una acera?","<strong>1,00 m</strong>.");
add(19,"Prohibición","¿Qué desniveles están terminantemente prohibidos en las aceras?","Los desniveles en <strong>sentido transversal</strong>.");
add(19,"Regla","¿Qué es obligatorio construir en las esquinas de las aceras?","<strong>Recesos para discapacitados</strong> (rampas), según las normas vigentes.");
// Art. 20
add(20,"Condición","¿Qué dos condiciones habilitan a exigir franjas verdes en la acera?","1) Acera de ancho <strong>superior a 3,00 m</strong>.<br>2) Que el <strong>carácter de la vía o del sector lo aconseje</strong>.");
add(20,"Facultad","¿Quién puede exigir las franjas verdes y con qué carácter?","La <strong>Municipalidad de Viedma</strong>; es <strong>facultativo</strong> (“podrá exigir”).");
add(20,"Dato","¿Dónde se ubican las franjas verdes y qué ancho mínimo tienen?","<strong>Contiguas al cordón</strong>, de <strong>no menos de 1,00 m</strong>.");
add(20,"Excepción","¿En qué casos se interrumpen las franjas verdes?","<ul><li>En las <strong>esquinas</strong></li><li>En <strong>paradas de ómnibus</strong></li><li>En <strong>accesos o guardacoches</strong></li></ul>");
add(20,"Dato","¿Hasta qué distancia se interrumpe la franja verde en las esquinas y desde dónde se mide?","Hasta <strong>9,00 m</strong>, medidos desde la <strong>intersección de los cordones</strong>.");
add(20,"Caso","Acera de exactamente 3,00 m: ¿por qué no habilita a exigir franja verde?","Porque se requiere un ancho <strong>superior</strong> a 3,00 m.");
// Art. 21
add(21,"Dato","¿Qué forma y medida deben tener las cazuelas para arbolado?","<strong>Cuadradas</strong>, de <strong>0,80 m de lado</strong>.");
add(21,"Dato","¿A qué distancia del cordón se ubican las cazuelas?","A <strong>0,20 m</strong> del cordón.");
add(21,"Dato","¿Cómo se protegen los bordes de las cazuelas?","Con un <strong>cordón de 0,10 m de espesor</strong> que <strong>no puede sobrepasar el nivel de vereda</strong>.");
add(21,"Dato","¿Qué distancia debe haber entre huecos de cazuelas?","<strong>5,00 m</strong>.");
add(21,"Regla","¿Qué es obligatorio plantar en las cazuelas y quién determina las especies?","<strong>Especies arbóreas adecuadas</strong>, determinadas por la <strong>oficina técnica municipal</strong> correspondiente, <strong>previa solicitud expresa</strong>.");
// Art. 22
add(22,"Regla","¿Con qué se relaciona el nivel de la acera y quién lo fija?","Con el <strong>nivel de la calzada</strong>; lo fija <strong>en cada caso el Organismo de Aplicación</strong>.");
add(22,"Dato","¿Qué pendiente transversal debe tener la acera?","Del <strong>0,2 % al 0,5 %</strong>.");
add(22,"Excepción","¿Qué pendiente se admite en las entradas de vehículos?","Hasta el <strong>10 %</strong>.");
add(22,"Prohibición","¿Qué no puede afectar, en principio, a los cordones de las aceras?","<strong>Recesos</strong> para estacionamiento u otros fines semejantes que <strong>afecten su continuidad</strong>.");
add(22,"Excepción","¿Quién puede autorizar recesos en los cordones y por qué motivo?","<strong>Sólo la Municipalidad</strong>, por <strong>razones de interés general</strong>.");
add(22,"Prohibición","¿Qué no se admite entre veredas contiguas?","El <strong>escalón</strong>.");
add(22,"Dato","¿Cómo se salva una diferencia de nivel en una vereda existente?","Con <strong>rampas del 2 % al 5 %</strong>.");
add(22,"Distinción","Pendientes de aceras: ¿qué valores rigen para la pendiente transversal, la entrada de vehículos y la rampa entre veredas?","Transversal: <strong>0,2 %–0,5 %</strong>.<br>Entrada de vehículos: <strong>hasta 10 %</strong>.<br>Rampa por desnivel entre veredas: <strong>2 %–5 %</strong>.");
// Art. 23
add(23,"Facultad","Respecto de las aceras, ¿qué puede exigir la Municipalidad según el carácter de la vía, y con qué piso mínimo?","El cumplimiento de <strong>normas particulares</strong>, adjuntando <strong>como mínimo las de los artículos precedentes</strong> (aceras).");
// Art. 24
add(24,"Dato","¿Según qué criterios se clasifican los patios?","Según sus <strong>dimensiones y función</strong>.");
add(24,"Regla","¿A qué clases de locales sirve un patio de 1ª categoría?","A locales de <strong>1ª, 3ª y 5ª clase</strong>.");
add(24,"Regla","¿A qué clase de locales sirve un patio de 2ª categoría?","A locales de <strong>2ª clase</strong>.");
add(24,"Definición","¿Qué locales son de 1ª clase?","Dormitorio, comedor, sala, living, biblioteca, estudio, consultorio, oficina, escritorio y <strong>todo local habitable no clasificado de otro modo</strong>.");
add(24,"Definición","¿Qué locales son de 2ª clase?","Cocina, cuarto de baño, orinal, lavadero, guardarropa o vestuario colectivo, cuarto de costura y cuarto de planchar.");
add(24,"Definición","¿Qué locales son de 3ª clase?","Locales de <strong>comercio y/o trabajo</strong>, depósitos comerciales/industriales, vestuario colectivo de club o asociación, <strong>gimnasios y locales de deporte</strong>, y <strong>cocinas de hotel, restaurante</strong>, casa de comidas, comedor colectivo y similares.");
add(24,"Definición","¿Qué locales son de 4ª clase?","Pasaje, corredor, vestíbulo, salita de espera anexa, guardarropa, cuarto de roperos/vestir anexo a dormitorio, tocador, despensa, antecomedor o espacio para cocinar, depósito no comercial ni industrial, <strong>sala de cirugía, rayos X</strong> y laboratorio fotográfico.");
add(24,"Definición","¿Qué locales son de 5ª clase?","<strong>Auxiliares para servicios generales</strong> del edificio: portería, administración, cuarto de máquinas, dependencias del personal de servicio, salas comunes de juegos infantiles.");
add(24,"Regla","¿Por dónde deben tener salida los locales de 5ª clase?","Sobre <strong>pasajes y corredores generales o públicos</strong>, <strong>no directamente sobre la vía pública</strong>.");
add(24,"Condición","¿Qué condiciones debe cumplir un depósito anexo para ser local de 4ª clase?","Hasta <strong>250 m²</strong> como máximo, y formar con el local <strong>una sola unidad de uso</strong>.");
add(24,"Facultad","¿Qué puede hacer el Organismo de Aplicación con el destino de los locales y con los no incluidos en la clasificación?","<strong>Presumir el destino</strong> a su exclusivo criterio y <strong>clasificar por analogía</strong> los locales no incluidos.");
add(24,"Distinción","¿En qué clase se ubica la cocina de un restaurante y en cuál la de una vivienda?","Restaurante: <strong>3ª clase</strong>.<br>Vivienda: <strong>2ª clase</strong>.");
add(24,"Caso","Un consultorio médico: ¿qué clase de local es y qué categoría de patio puede iluminarlo?","Local de <strong>1ª clase</strong>; patio de <strong>1ª categoría</strong>.");
// Art. 25
add(25,"Regla","¿Qué patios deben cumplir las normas de dimensiones de patios del Código?","Los <strong>proyectados para iluminación y/o ventilación</strong> de locales.");
// Art. 26
add(26,"Dato","¿Qué círculo debe poder inscribirse en un patio de 1ª categoría?","Uno de diámetro <strong>D = 1/5 H</strong>.");
add(26,"Definición","En el patio de 1ª categoría, ¿qué es H?","La distancia entre el <strong>piso del local a ventilar en el arranque del patio</strong> y el <strong>nivel del techo</strong>.");
add(26,"Dato","¿Qué valor mínimo puede tener D en un patio de 1ª categoría?","<strong>3,00 m</strong>.");
add(26,"Dato","¿Qué área mínima debe tener un patio de 1ª categoría?","<strong>12 m²</strong>.");
add(26,"Dato","Patio de 1ª categoría común a unidades funcionales enfrentadas: ¿qué lado mínimo debe tener?","<strong>4 m</strong>.");
add(26,"Caso","Patio de 1ª categoría con H = 20 m. ¿Qué diámetro D debe poder inscribirse?","<strong>4 m</strong> (20 ÷ 5).");
add(26,"Caso","Patio de 1ª categoría con H = 10 m. ¿Qué diámetro D se exige?","<strong>3,00 m</strong>: el cálculo da 2 m, pero rige el <strong>mínimo de 3,00 m</strong>.");
// Art. 27
add(27,"Dato","¿Qué área mínima debe tener en su arranque un patio de 2ª categoría?","<strong>8,00 m²</strong>.");
add(27,"Dato","¿Qué ancho mínimo debe tener un patio de 2ª categoría y en qué extensión?","<strong>2,00 m</strong>, en <strong>toda su altura</strong>.");
add(27,"Distinción","Patio de 1ª vs. 2ª categoría: área y medida lineal mínimas.","1ª: <strong>12 m²</strong> y D mínimo <strong>3,00 m</strong>.<br>2ª: <strong>8 m²</strong> y ancho mínimo <strong>2,00 m</strong>.");
// Art. 28
add(28,"Regla","¿Cómo se miden los patios?","En la <strong>proyección horizontal del edificio</strong>.");
add(28,"Dato","¿Qué elementos se excluyen al medir un patio?","<strong>Aleros, cornisas, escaleras, espesores de muros medianeros, voladizos</strong>, etc.");
add(28,"Regla","¿Qué condición de acceso deben cumplir los patios?","Ser <strong>accesibles para su limpieza</strong>.");
add(28,"Prohibición","¿Qué prohíbe el Código respecto de la cubierta de los patios?","Que sean <strong>techados</strong>.");
add(28,"Excepción","¿Con qué elemento puede cubrirse un patio?","Con <strong>toldos móviles</strong>.");
// Art. 29
add(29,"Dato","Vivienda permanente de un solo local habitable: ¿qué medidas mínimas tiene?","<strong>18 m²</strong> y <strong>3,00 m de lado</strong>.");
add(29,"Dato","Vivienda de dos o más locales habitables: ¿qué medidas mínimas corresponden?","Uno de <strong>12 m² y 3 m de lado</strong>; los demás de <strong>8 m² y 2,00 m de lado</strong>.");
add(29,"Regla","¿Qué normas se adoptan para residencias de carácter transitorio (hoteles, pensiones, hosterías)?","Las de la <strong>Secretaría de Estado de Turismo de la Nación</strong>, con los mínimos del Art. 29.");
add(29,"Dato","Residencias transitorias: medidas mínimas de habitaciones para 1, 2 y 3 personas.","1 persona: <strong>7,50 m²</strong>.<br>2 personas: <strong>9 m²</strong>.<br>3 personas: <strong>16 m²</strong>.<br>Lado mínimo en todos los casos: <strong>2,50 m</strong>.");
add(29,"Dato","Oficinas: ¿qué medidas mínimas tiene un local individual?","<strong>12 m²</strong> y <strong>3 m de lado</strong>.");
add(29,"Dato","Oficinas con más de 2 locales: ¿qué medidas mínimas corresponden?","Uno de <strong>9 m² y 2,50 m</strong>; los restantes de <strong>7,50 m² y 2,50 m</strong>.");
add(29,"Dato","Locales comerciales, de trabajo, depósitos, gimnasios, comedores colectivos y cocinas de hotel o restaurante: ¿qué medidas mínimas tienen?","<strong>16 m²</strong> y <strong>3 m de lado</strong>.");
add(29,"Dato","¿Qué superficie por persona se calcula para comedores colectivos?","<strong>0,90 m² por persona</strong>.");
add(29,"Dato","¿Qué superficie por persona se calcula para cocinas (excluidas otras dependencias)?","<strong>0,10 m² por persona</strong>.");
add(29,"Dato","¿Qué superficie por persona se calcula para vestuarios colectivos?","<strong>0,50 m² por persona</strong>.");
add(29,"Dato","¿Qué medidas mínimas tiene una cocina?","<strong>3 m²</strong> y <strong>1,30 m de lado</strong>.");
add(29,"Regla","¿En función de qué se fijan las medidas de baños y retretes?","Del <strong>número de artefactos</strong> a instalar.");
add(29,"Dato","Baño con bañera, inodoro, bidet y lavabo: ¿qué medidas mínimas tiene?","<strong>3,00 m²</strong> y <strong>1,20 m de lado</strong>.");
add(29,"Dato","Baño con ducha, inodoro, bidet y lavabo: ¿qué medidas mínimas tiene?","<strong>2,60 m²</strong> y <strong>1,10 m de lado</strong>.");
add(29,"Dato","Baño con ducha, inodoro y lavabo: ¿qué medidas mínimas tiene?","<strong>1,50 m²</strong> y <strong>1,00 m de lado</strong>.");
add(29,"Dato","Baño con ducha e inodoro: ¿qué medidas mínimas tiene?","<strong>1,20 m²</strong> y <strong>0,80 m de lado</strong>.");
add(29,"Dato","Local sólo con ducha y local sólo con inodoro: ¿qué medidas mínimas tienen?","Sólo ducha: <strong>0,70 m²</strong>.<br>Sólo inodoro: <strong>0,90 m²</strong>.<br>Lado mínimo en ambos: <strong>0,80 m</strong>.");
add(29,"Regla","¿Cómo se consideran las superficies mínimas de los locales (habitaciones, baños, cocinas)?","<strong>Mínimas, libres y netas</strong>, excluyendo muros con revestimientos, armarios, botiquines, etc.");
add(29,"Caso","Un comedor colectivo para 50 personas: ¿qué superficie necesita por cálculo?","<strong>45 m²</strong> (50 × 0,90).");
add(29,"Caso","Una vivienda tiene tres locales habitables. ¿Qué medidas mínimas corresponden a cada uno?","Uno de <strong>12 m² y 3 m de lado</strong>; los otros dos de <strong>8 m² y 2 m de lado</strong>.");
// Art. 30
add(30,"Dato","¿Qué servicios mínimos de salubridad debe tener todo predio edificado?","<ul><li>Un <strong>retrete con inodoro</strong></li><li>Una <strong>pileta de lavar</strong></li><li>Una <strong>ducha o bañera</strong> con desagües</li><li><strong>Digestor y pozo absorbente calzado</strong></li></ul>");
add(30,"Dato","¿Cómo debe ser el retrete mínimo exigido?","De <strong>mampostería u hormigón</strong>, con <strong>solado impermeable</strong> y dotado de <strong>inodoro</strong>.");
add(30,"Regla","Servicio mínimo de salubridad de todo predio: además del digestor y pozo absorbente calzado, ¿qué exigencias deben cumplirse y de quién?","Las del reglamento particular o del <strong>Departamento Provincial de Aguas y/o ARSA</strong>.");
// Art. 31
add(31,"Regla","¿A qué edificios se aplica la escala de inodoros, mingitorios y lavabos según la cantidad de personas?","Edificios <strong>públicos, comerciales, industriales</strong> o locales destinados a esos fines, sin perjuicio de otras reglamentaciones.");
add(31,"Dato","Edificio público, comercial o industrial con menos de 5 personas: ¿qué servicios sanitarios se exigen?","<strong>1 inodoro</strong> y <strong>1 lavabo con canilla</strong>.");
add(31,"Regla","Edificio público, comercial o industrial con más de 5 personas: ¿qué cambia en los servicios sanitarios?","Deben ser <strong>separados por sexo</strong>.");
add(31,"Dato","Edificio público, comercial o industrial: ¿qué artefactos para hombres corresponden hasta 20 personas?","<strong>1 inodoro y 1 mingitorio</strong> (igual hasta 10 que hasta 20).");
add(31,"Dato","Edificio público, comercial o industrial: ¿qué artefactos para hombres corresponden hasta 40 personas?","<strong>2 inodoros y 2 mingitorios</strong>.");
add(31,"Dato","Edificio público, comercial o industrial: ¿qué artefactos para hombres corresponden con más de 40 personas?","<strong>1 inodoro y 1 mingitorio por cada 30 hombres o fracción</strong>.");
add(31,"Dato","Edificio público, comercial o industrial: ¿cuántos inodoros para mujeres corresponden hasta 30 y con más de 30?","Hasta 30: <strong>2 inodoros</strong>.<br>Más de 30: <strong>1 inodoro más por cada 20 personas adicionales</strong>.");
add(31,"Distinción","Edificio público, comercial o industrial con hasta 60 personas: ¿qué proporción de lavabos rige para hombres y cuál para mujeres?","Hombres: <strong>1 cada 20</strong>.<br>Mujeres: <strong>1 cada 10</strong>.");
add(31,"Dato","Edificio público, comercial o industrial con más de 60 personas: ¿qué proporción de lavabos rige?","<strong>1 cada 20 personas o fracción</strong>, para ambos sexos.");
// Art. 32
add(32,"Regla","¿Dónde están fijadas las alturas mínimas de los locales?","En la <strong>planilla del Anexo I</strong>.");
add(32,"Dato","Según el Anexo I, ¿qué altura mínima tienen dormitorio, estar, comedor y escritorio?","<strong>2,40 m</strong>.");
add(32,"Dato","Según el Anexo I, ¿qué altura mínima tienen cocina, baño, lavadero familiar y despensa familiar?","<strong>2,20 m</strong>.");
add(32,"Dato","Según el Anexo I, ¿qué altura mínima tienen un aula y un salón de baile?","<strong>3,00 m</strong>.");
// Art. 33
add(33,"Facultad","En edificios de uso público, ¿qué puede exigir el Organismo de Aplicación respecto de las alturas?","<strong>Alturas mayores</strong> a las previstas.");
// Art. 34
add(34,"Regla","¿Qué puede tener todo local respecto de su altura, cumpliendo condiciones?","<strong>Entrepisos o niveles intermedios</strong> de altura menor a la establecida.");
add(34,"Dato","¿Qué altura mínima de paso deben tener el entrepiso y la parte que cubre?","<strong>2,20 m en cada uno</strong>, libres de vigas, espesor de losa, etc.");
add(34,"Dato","¿Qué superficie máxima puede cubrir un entrepiso dentro de un local?","<strong>La mitad del área</strong> del local.");
add(34,"Condición","¿Qué relación espacial debe haber entre un entrepiso y el local donde está?","<strong>Completa continuidad espacial</strong>; los locales sólo pueden <strong>cerrarse parcialmente</strong>.");
add(34,"Caso","Un local de 40 m² quiere un entrepiso de 25 m². ¿Qué superficie máxima admite?","<strong>20 m²</strong> (la mitad del local).");
// Art. 35
add(35,"Regla","En locales con desniveles de cielorraso o piso, ¿cómo se calcula la altura que debe igualar la mínima?","<strong>Altura media = volumen ÷ superficie</strong> del local.");
add(35,"Dato","En locales con desniveles de cielorraso o piso, ¿qué altura mínima debe haber en el punto más bajo?","<strong>2,20 m</strong>.");
// Art. 36
add(36,"Regla","¿Con qué elementos se cierran los vanos de iluminación?","Puertas vidrieras, ventanas, banderolas, <strong>ladrillos de vidrio</strong> o cualquier <strong>elemento traslúcido</strong> que transmita luz efectivamente.");
// Art. 37
add(37,"Regla","¿Cómo se obtiene la ventilación de los locales?","Haciendo que <strong>parte o la totalidad de los vanos puedan abrirse</strong>.");
// Art. 38
add(38,"Prohibición","¿Dónde está prohibido ubicar vanos de iluminación y/o ventilación?","En <strong>muros divisorios de predios (medianeras)</strong>.");
// Art. 39
add(39,"Regla","¿De qué depende la superficie de los vanos de iluminación y ventilación?","Del <strong>destino, superficie, forma y altura</strong> del local.");
add(39,"Definición","¿Qué significan I, V y S en las fórmulas de iluminación y ventilación?","<strong>I</strong>: área de iluminación.<br><strong>V</strong>: área de ventilación.<br><strong>S</strong>: área del local.");
// Art. 40
add(40,"Dato","Vano directo al exterior: ¿qué valores de I y V se exigen?","<strong>I = S/10</strong> · <strong>V = I/2</strong>.","1");
add(40,"Dato","Vano al exterior bajo parte cubierta: ¿qué valores de I y V se exigen?","<strong>I = S/6</strong> · <strong>V = I/2</strong>.","2");
add(40,"Dato","Iluminación vertical o cenital: ¿qué valores de I y V se exigen?","<strong>I = S/15</strong> · <strong>V = I/2</strong>, con <strong>V mínimo 0,25 m²</strong>.","3");
add(40,"Regla","En la iluminación directa, bajo parte cubierta y cenital, ¿qué relación guarda siempre V con I?","<strong>V es la mitad de I</strong>.","1,2,3");
add(40,"Regla","Para escaleras con iluminación cenital, ¿qué se toma como S?","La <strong>suma del área de la caja de todos los pisos</strong>.","3");
add(40,"Caso","Dormitorio de 12 m² con ventana directa al exterior: ¿qué I y V corresponden?","<strong>I = 1,20 m²</strong> · <strong>V = 0,60 m²</strong>.","1");
add(40,"Caso","Local de 15 m² con ventana bajo una galería: ¿qué I y V corresponden?","<strong>I = 2,50 m²</strong> · <strong>V = 1,25 m²</strong>.","2");
add(40,"Condición","¿Qué locales deben tener ventilación mecánica además de la ventilación exigida?","Los <strong>locales de salubridad en lugares de espectáculos y diversión públicos</strong>.","4");
add(40,"Dato","Locales de salubridad en espectáculos públicos: ¿qué renovación de aire debe asegurar la ventilación mecánica y con cuántos equipos?","<strong>10 veces el volumen del local por hora</strong>, con <strong>dos equipos</strong>: uno en uso y otro auxiliar.","4");
add(40,"Regla","Locales de salubridad en espectáculos públicos: ¿cuándo deben funcionar los equipos de ventilación mecánica y qué indicador llevan?","En forma obligatoria en <strong>horas de función</strong>, con una <strong>luz piloto</strong> que indique su funcionamiento.","4");
add(40,"Dato","Baño o cocina en planta baja que ventila a la vía pública: ¿a qué altura va la boca de salida?","Como mínimo a <strong>2,00 m sobre el nivel de vereda</strong>.","5");
add(40,"Excepción","¿Qué edificaciones quedan exceptuadas de la altura de 2,00 m de la boca de ventilación de baños y cocinas en planta baja?","Las <strong>retiradas de la L.M.</strong>","5");
add(40,"Regla","En locales de comercio sobre pasajes, ¿cómo se considera el pasaje y qué ventilación extra se exige?","El pasaje se considera <strong>vía pública</strong>; además, <strong>ventilación auxiliar obligatoria</strong> (cenital o por tubo común) en el <strong>lado opuesto</strong> al vano sobre el pasaje.","6");
add(40,"Dato","Tubo de ventilación independiente: ¿qué sección mínima debe tener?","<strong>S/400</strong>, y nunca menos de <strong>0,03 m²</strong>.","7");
add(40,"Dato","Tubos de ventilación independientes y comunes: ¿qué inclinación máxima admiten?","Verticales o inclinados <strong>no más de 45°</strong>.","7,8");
add(40,"Dato","Tubo independiente: ¿cómo debe ser la abertura que comunica el local con el tubo?","<strong>Regulable</strong> y de área <strong>no inferior al conducto</strong>.","7");
add(40,"Dato","Tubos de ventilación independientes y comunes: ¿qué longitud máxima pueden tener los tramos horizontales?","<strong>¼ de la altura propia</strong> del conducto.","7,8");
add(40,"Dato","Tubos de ventilación independientes y comunes: ¿cómo y a qué altura rematan en la azotea?","A los <strong>4 vientos con sombrerete</strong>, a <strong>1,50 m</strong> sobre cualquier solado o coronamiento de muro.","7,8");
add(40,"Regla","¿Para qué sirve el tubo de ventilación común?","Para <strong>unificar dos o más tubos independientes</strong>.","8");
add(40,"Dato","Tubo de ventilación común: ¿de qué material es y qué no puede alojar?","De <strong>mampostería u hormigón</strong>; dentro no se ubican <strong>desagües ni cañerías</strong>.","8");
add(40,"Dato","Tubo de ventilación común: ¿qué sección mínima y qué relación de lados debe tener?","Sección <strong>no inferior a 0,60 m²</strong>; relación de lados <strong>no mayor de 1/3</strong>.","8");
add(40,"Dato","¿Cómo remata el conducto de cada local en el tubo de ventilación común?","Con un <strong>recorrido vertical mínimo de 1,00 m</strong> y una <strong>diferencia de nivel de salida mínima de 0,50 m</strong>.","8");
add(40,"Caso","Local de 8 m² ventilado por tubo independiente: ¿qué sección mínima corresponde?","<strong>0,03 m²</strong>: S/400 da 0,02 m², pero rige el <strong>mínimo de 0,03 m²</strong>.","7");
// Art. 41
add(41,"Regla","¿Qué carácter tienen las condiciones de iluminación y ventilación consignadas en la tabla del Anexo I?","Son <strong>optativas</strong>: puede tomarse <strong>cualquiera</strong> de las consignadas.");
add(41,"Regla","En la tabla de iluminación y ventilación del Anexo I, ¿qué significa que el número de una condición esté entre paréntesis?","Que el local debe cumplir <strong>además con cualquiera de las otras condiciones</strong> consignadas.");
// Art. 42
add(42,"Regla","¿Cómo se determina el destino de cada local?","Por lo que <strong>lógicamente resulte de su ubicación y dimensiones</strong>, no por lo que se consigne arbitrariamente en los planos.");
add(42,"Facultad","¿Qué proyectos puede rechazar el Organismo de Aplicación por el destino de los locales?","Plantas cuyos locales <strong>acusen intención de una división futura</strong>.");
// Art. 43
add(43,"Regla","¿Qué finalidad tienen las normas sobre tabiques, puertas y entrepisos entre unidades habitables?","Preservar las <strong>condiciones acústicas</strong>, evitando la propagación de ruidos o vibraciones por <strong>vía sólida o aérea</strong>.");
add(43,"Dato","Tabique simple de ladrillos macizos entre unidades: ¿qué espesor y terminación lleva?","<strong>0,15 m</strong>, revocado a la cal o yeso <strong>en ambos paramentos</strong>.");
add(43,"Dato","Tabique simple de bloques de hormigón hueco: ¿qué espesor lleva?","<strong>0,20 m</strong>, revocado en ambos paramentos.");
add(43,"Dato","Doble tabique de ladrillos macizos: ¿qué espacio queda entre ellos y qué está prohibido?","<strong>0,075 m</strong>, sin <strong>ninguna conexión</strong> entre ambos (ladrillos, varillas, zunchos).");
add(43,"Dato","Doble tabique de bloques de hormigón hueco: ¿qué espesor tiene cada uno?","<strong>0,10 m</strong> cada uno, sin conexión entre ambos.");
add(43,"Dato","Tabique de hormigón armado macizo: ¿qué espesor y densidad se exigen?","<strong>0,10 m</strong> de espesor y <strong>2.400 kg/m³</strong>.");
add(43,"Dato","Tabique de bloques cerámicos huecos: ¿qué espesor lleva?","<strong>0,08 m</strong>, revocado en ambos paramentos.");
add(43,"Condición","¿Qué requisito deben cumplir los sistemas prefabricados para usarse como divisorios entre unidades?","Contar con <strong>Certificado de Aptitud Técnica</strong> de la Secretaría de Desarrollo Urbano y Vivienda, <strong>actualizado</strong>.");
add(43,"Regla","¿Cómo deben ser las puertas de acceso a unidades de vivienda?","<strong>Macizas</strong> y de <strong>contacto perfecto en sus cuatro lados</strong>.");
add(43,"Excepción","¿Qué accesos a unidades de vivienda quedan exceptuados de tener puerta maciza?","Los que tengan <strong>doble puerta común</strong> (pasillos de acceso, zaguanes, hall de entrada).");
add(43,"Dato","Entrepisos entre unidades habitables: ¿qué losa y contrapiso se exigen?","Losa de <strong>HºAº de 0,10 m</strong> (o equivalente acústico) con <strong>contrapiso de 0,07 m</strong>.");
// Art. 44
add(44,"Regla","Ante instalaciones que producen ruidos o vibraciones, ¿qué precauciones exige el Código?","Tomar precauciones para que <strong>no se transmitan por vía sólida o aérea</strong> a otros ambientes del edificio o a otros edificios.");
add(44,"Dato","¿Qué instalaciones menciona el Código como posibles fuentes de ruido o vibración?","Ascensores, tuberías de bombas de fluidos, aparatos climáticos y/o sanitarios, <strong>canchas de pelota, bochas</strong> o similares (y “moteles”, según el texto).");
// Art. 45
add(45,"Regla","¿Qué debe ejecutarse obligatoriamente sobre el terreno para colocar los pisos?","<strong>Contrapiso con aislación hidrófuga</strong>.");
add(45,"Dato","¿Qué trabajos sobre el suelo vincula el Código con la ejecución del contrapiso con aislación hidrófuga?","<strong>Limpieza del suelo</strong>, <strong>eliminación de tierra negra o materia orgánica</strong> y <strong>consolidación</strong>.");
add(45,"Dato","Muros en contacto con el terreno: ¿qué aislación deben tener y dónde se ubica?","<strong>Doble capa aisladora (horizontal y vertical)</strong> hidrófuga, <strong>más arriba del nivel del solado</strong> y unida al contrapiso; cualquiera sea su espesor, internos o externos.");
add(45,"Dato","Locales total o parcialmente bajo el nivel del terreno: ¿qué se construye del lado externo?","Un <strong>tabique de ladrillo de panderete</strong> (de <strong>hormigón</strong> si hay mucha profundidad), con <strong>revoque hidrófugo</strong> unido a la capa aisladora horizontal.");
add(45,"Dato","Locales con instalaciones sanitarias: ¿hasta qué altura deben ser impermeables pisos y paredes?","Hasta <strong>1,50 m</strong>, en las proximidades de las bocas de salida de líquido.");
add(45,"Condición","¿Qué se requiere para arrimar canteros a muros separativos de viviendas?","Prever un <strong>aislamiento hidrófugo vertical</strong>.");
add(45,"Regla","¿Qué aislación deben tener los muros exteriores?","<strong>Aislación hidrófuga permanente</strong>.");
add(45,"Regla","¿Qué reglamentaciones deben cumplir los desagües?","Las del <strong>D.P.A.</strong> (Departamento Provincial de Aguas).");
// Art. 46
add(46,"Condición","¿Qué edificios deben asegurar su rápida evacuación mediante medios de egreso?","Los de <strong>más de dos unidades independientes</strong> y/o destinados a <strong>concentración de público</strong> (cubierto o descubierto).");
add(46,"Dato","Puerta de unidad independiente a pasajes o corredores comunes: ¿qué ancho y altura mínimos tiene?","<strong>0,90 m libres</strong> hasta 50 personas o fracción; altura mínima <strong>2,00 m</strong>.","1");
add(46,"Regla","Medios de egreso: cuando hay escaleras, ¿hacia dónde deben abrir las puertas de las unidades?","Sobre un <strong>descanso</strong>.","1");
add(46,"Dato","Concentración de público: ¿cómo se calcula el ancho total de puertas de egreso y qué mínimo tiene?","<strong>0,01 m por persona</strong>, nunca menos de <strong>1,50 m</strong>.","2");
add(46,"Dato","Medios de egreso: ¿cómo se calcula el ancho de los pasajes o corredores que conectan con la vía pública y qué mínimo tienen?","Se calculan a 0,01 m por persona, con mínimo de <strong>1,20 m</strong>.","3");
add(46,"Dato","¿Qué ancho libre mínimo tiene un pasaje comercial de uso público?","<strong>3,00 m</strong>.","4");
add(46,"Dato","Escalera de egreso: ¿qué ancho libre mínimo tiene?","<strong>0,90 m</strong>.","5");
add(46,"Dato","Escalera de egreso: ¿qué huella mínima y alzada máxima tiene?","Huella mínima <strong>0,26 m</strong>; alzada máxima <strong>0,18 m</strong>.","5");
add(46,"Dato","Escalera de egreso: ¿qué altura máxima puede salvarse sin descanso?","<strong>3,00 m</strong>.","5");
add(46,"Dato","Escalera de tramos curvos: ¿dónde se mide la huella mínima de 0,26 m?","En el <strong>centro de giro</strong> si el ancho es de hasta 0,90 m; a <strong>0,45 m del limón inferior</strong> si es mayor.","5");
add(46,"Regla","En lugares de concentración de público, ¿cómo se calcula el ancho de las escaleras?","Igual que las puertas de egreso: <strong>0,01 m por persona</strong>.","6");
add(46,"Dato","Medios de egreso: ¿qué distancia máxima entre circulaciones verticales rige según el destino del edificio?","Concentración de público, comercial, industrial o depósitos: <strong>45 m</strong>.<br>Residencial, instituciones o semejantes: <strong>30 m</strong>.","7");
add(46,"Dato","Escaleras que no son egreso ni acceso obligado: ¿qué ancho, huella y alzada tienen?","Ancho <strong>0,70 m</strong>; huella mínima <strong>0,23 m</strong>; alzada máxima <strong>0,20 m</strong>.","8");
add(46,"Caso","Salón para 200 personas: ¿qué ancho total de puertas de egreso necesita?","<strong>2,00 m</strong> (200 × 0,01).","2");
add(46,"Caso","Salón para 120 personas: ¿qué ancho total de puertas de egreso necesita?","<strong>1,50 m</strong>: el cálculo da 1,20 m, pero rige el <strong>mínimo de 1,50 m</strong>.","2");
// Art. 47
add(47,"Regla","¿Qué protección deben tener todas las escaleras?","<strong>Barandas o pasamanos rígidos</strong>, al menos en <strong>uno de sus lados</strong>.");
add(47,"Excepción","¿Cuándo deben colocarse barandas en ambos lados de la escalera?","Cuando su ancho <strong>supere 1,40 m</strong>.");
// Art. 48
add(48,"Regla","¿Con qué materiales deben ejecutarse las escaleras reglamentarias?","Con materiales <strong>incombustibles</strong>.");
// Art. 49
add(49,"Condición","¿Cuándo se consideran las rampas como medios de egreso?","Cuando por <strong>ubicación, construcción y ancho</strong> cumplen los artículos anteriores.");
add(49,"Dato","¿Qué pendiente máxima y qué solado debe tener una rampa de egreso?","Pendiente máxima <strong>12 %</strong>; solado <strong>antideslizante</strong>.");
// Art. 50
add(50,"Prohibición","Medios de egreso: ¿qué puertas no se computan como aberturas de salida?","Las <strong>puertas vaivén</strong>.");
add(50,"Excepción","¿En qué edificios y en qué proporción se computan las puertas giratorias como salida?","En edificios <strong>residenciales y de oficinas</strong>, hasta el <strong>50 % del ancho exigido</strong>.");
add(50,"Dato","¿Qué diámetro mínimo tiene una puerta giratoria?","<strong>1,65 m</strong>.");
add(50,"Regla","Si se computan puertas giratorias como salida, ¿cómo se cubre el 50 % restante del ancho exigido?","Obligatoriamente con <strong>puertas de abrir</strong>.");
// Art. 51
add(51,"Regla","¿Qué reglamento fija las reglas básicas de seguridad estructural de toda edificación?","El <strong>Reglamento Técnico de Estructuras</strong>, sin perjuicio de otras reglas del arte.");
add(51,"Regla","¿Qué reglamento rige las estructuras de hormigón armado?","El <strong>PRAEH</strong>.");
// Art. 52
add(52,"Regla","¿Qué libertad hay en la elección del procedimiento de cálculo estructural?","Es <strong>libre</strong>.");
add(52,"Condición","Si en el cálculo estructural se usan fórmulas nuevas, ¿qué debe hacerse?","Hacer constar su <strong>procedencia y justificación</strong> y obtener la <strong>aprobación del Organismo de Aplicación</strong>.");
add(52,"Dato","¿Qué exactitud mínima se exige en el cálculo estructural?","La de una <strong>regla de cálculo de 0,25 m</strong> o un procedimiento gráfico equivalente.");
// Art. 53
add(53,"Regla","¿Dónde debe proyectarse y ejecutarse la estructura resistente?","<strong>Dentro de los límites del predio</strong>.");
add(53,"Excepción","¿Qué elemento puede asentarse en ambos predios colindantes?","Un <strong>muro divisorio con su cimiento</strong>.");
add(53,"Regla","¿Dónde deben ejecutarse los muros privativos contiguos a predios linderos?","<strong>Dentro del propio predio</strong>, sean o no resistentes.");
// Art. 54
add(54,"Dato","¿Qué espesor mínimo tienen los muros portantes según el material?","Ladrillos comunes: <strong>0,30 m</strong>.<br>Ladrillos huecos y bloques de cemento: <strong>0,20 m</strong>.");
add(54,"Excepción","¿Cuándo se permiten muros portantes de 0,15 m?","Si la pared <strong>no supera 3,00 m de altura</strong> y tiene <strong>encadenamiento de HºAº en su parte superior</strong>.");
add(54,"Dato","¿Con qué material, espesor y ubicación se ejecutan los muros medianeros?","<strong>Ladrillos comunes</strong>, mínimo <strong>0,30 m</strong>, materializados <strong>a eje divisorio</strong>.");
// Art. 55
add(55,"Dato","¿Qué protección deben tener techos y azoteas transitables?","<strong>Barandas o parapetos de 1,00 m</strong> de altura desde el solado.");
// Art. 56
add(56,"Dato","Cubierta sobre locales habitables: ¿qué cualidades debe tener el material?","<strong>Impermeable, imputrescible y mal conductor térmico</strong> (teja, pizarra, fibrocemento o equivalente).");
add(56,"Distinción","¿Qué cualidades debe tener la cubierta de locales no habitables?","<strong>Impermeable e incombustible</strong>.");
// Art. 57
add(57,"Dato","¿Qué desagüe pluvial se exige en techos y azoteas, y en qué proporción?","Un <strong>caño de 4” de diámetro interno</strong> por cada <strong>80 m²</strong> de superficie.");
add(57,"Regla","¿Con qué puede conectarse el caño de desagüe pluvial de techos y azoteas, y cómo?","Con la <strong>calle o la red pluvial</strong>, mediante caños a <strong>nivel de calzada</strong> y con pendiente para el escurrimiento.");
// Art. 58
add(58,"Prohibición","¿Sobre qué no pueden desaguar los techos con caída libre?","Sobre <strong>predios linderos</strong> ni sobre la <strong>vía pública (vereda)</strong>.");
// Art. 59
add(59,"Regla","¿A qué deben ajustarse los cimientos de los muros de sótanos?","A lo dispuesto en el <strong>Art. 53</strong> (dentro del predio).");
// Art. 60
add(60,"Regla","¿Qué debe considerar el espesor de los muros envolventes de sótanos?","Condiciones <strong>estructurales</strong> y de <strong>aislación hidrófuga</strong>.");
// Art. 61
add(61,"Condición","¿Qué requisito deben cumplir los sistemas constructivos no tradicionales?","Contar con <strong>Certificado de Aptitud Técnica</strong> de la Secretaría de Estado de Desarrollo Urbano y Vivienda, <strong>actualizado al momento de la obra</strong>.");
// Art. 62
add(62,"Dato","¿Qué organismo fija las normas de las instalaciones sanitarias, eléctricas y de gas?","Sanitarias: <strong>Departamento Provincial de Aguas</strong>.<br>Eléctricas: <strong>Agua y Energía Eléctrica de la Nación</strong>.<br>Gas: <strong>Gas del Estado</strong>.");
add(62,"Condición","¿Qué condiciones deben cumplir los locales para medidores eléctricos?","<strong>Fácil acceso</strong>, <strong>buena ventilación e impermeabilización</strong>, y <strong>sin comunicación con locales con instalaciones de gas</strong>.");
add(62,"Dato","Baterías de medidores eléctricos: ¿a qué alturas van la fila inferior y la superior?","Inferior: <strong>no menos de 0,90 m</strong> del solado.<br>Superior: <strong>no más de 1,80 m</strong>.");
add(62,"Dato","¿Qué espacio libre debe quedar al frente de los medidores eléctricos?","<strong>1,00 m de ancho libre</strong> como mínimo.");
// Art. 63
add(63,"Dato","Locales para calderas y aparatos térmicos: ¿qué paso libre debe quedar alrededor de cada aparato?","<strong>0,60 m</strong> alrededor de todo su perímetro.");
add(63,"Dato","Locales para calderas: ¿qué altura libre sobre la maquinaria y qué altura mínima de local se exigen?","<strong>1,00 m</strong> sobre la maquinaria; local de <strong>2,50 m</strong> como mínimo.");
add(63,"Prohibición","¿Qué relación no pueden tener los locales de calderas con los medidores de gas?","<strong>No pueden tener conexión</strong> con los locales de medidores de gas <strong>ni contenerlos</strong>.");
// Art. 64
add(64,"Regla","¿Qué exige el Código para los conductos de aire acondicionado?","Que se <strong>aíslen convenientemente</strong> y <strong>no alojen otros conductos</strong>.");
// Art. 65
add(65,"Regla","¿Dónde deben construirse los pozos absorbentes y cámaras sépticas?","<strong>Totalmente dentro del predio</strong>.");
add(65,"Dato","¿Qué retiro deben tener pozos y cámaras sépticas respecto de edificaciones y ejes divisorios?","<strong>1,50 m</strong> como mínimo.");
add(65,"Dato","¿Hasta qué profundidad deben calzarse los pozos absorbentes?","Hasta <strong>2,50 m</strong>.");
add(65,"Dato","¿Con qué se cubren los pozos absorbentes y cómo se ventilan?","Con <strong>losa de HºAº o bóveda de mampostería</strong>; <strong>caño de ventilación</strong> desde la parte más alta, <strong>a los 4 vientos</strong>.");
add(65,"Regla","¿Qué conexión futura debe prever siempre la instalación de pozos y cámaras?","La conexión a la <strong>red cloacal</strong>.");
// Art. 66
add(66,"Regla","¿Qué debe asegurar la cota de la planta baja?","El <strong>desagüe pluvial a la vía pública</strong> y el <strong>cloacal a la red</strong> (si hubiera).");
add(66,"Dato","Sin proyecto de nivelación ni nivel de vereda, ¿qué cota exige la Municipalidad como nivel cero de planta baja?","<strong>0,50 m</strong> respecto del <strong>eje de la vía de acceso</strong>.");
// Art. 67
add(67,"Prohibición","¿Qué líquidos está prohibido lanzar y hacia dónde?","<strong>Líquidos cloacales y aguas servidas</strong> a la vía pública, terrenos propios o vecinos y cursos de agua.");
// Art. 68
add(68,"Regla","¿Qué normas rigen la construcción de panteones, sepulturas o monumentos?","Las de este Código para la <strong>edificación en general</strong>, <strong>en cuanto sean pertinentes</strong>.");
// Art. 69
add(69,"Facultad","¿Qué puede dictar la Municipalidad en el futuro sobre construcciones en cementerios?","<strong>Ordenanzas especiales</strong>, de acuerdo a su criterio.");
// Art. 70
add(70,"Regla","¿Qué edificios quedan sujetos a las normas especiales de prevención contra incendios?","Los de <strong>uso comercial</strong> y las <strong>viviendas colectivas en altura</strong>.");
add(70,"Dato","¿Qué normas de prevención contra incendios rigen para edificios comerciales y viviendas colectivas en altura?","La <strong>Ley 19.587</strong> de Seguridad e Higiene en el Trabajo y su <strong>Decreto Reglamentario 4100/73</strong>.");
// Art. 71
add(71,"Condición","¿Cuándo es obligatoria la valla provisoria en la acera?","Ante trabajos <strong>peligrosos, incómodos</strong> o que sean <strong>obstáculo para el tránsito</strong>.");
add(71,"Regla","¿Qué extensión y función debe tener la valla provisoria?","<strong>Toda la extensión del frente</strong>, construida para <strong>impedir la salida de material</strong> al exterior.");
add(71,"Dato","¿Qué paso libre y qué altura debe dejar la valla provisoria?","Paso libre mínimo de <strong>1,00 m</strong> de ancho; altura de <strong>2,40 m</strong>.");
// Art. 72
add(72,"Regla","¿Qué deben evitar las demoliciones?","<strong>Perjudicar los edificios linderos y el tránsito</strong> en la vía pública.");
add(72,"Dato","¿Qué cerco se exige en las demoliciones y con qué altura?","<strong>Cerco protector provisorio</strong> en toda la extensión del frente, de <strong>2,40 m</strong> de altura libre mínima.");
// Art. 73
add(73,"Regla","¿Cómo debe hacerse la demolición de los muros?","<strong>Paulatinamente</strong>, <strong>no por bloques</strong>.");
add(73,"Dato","¿Desde qué altura máxima pueden arrojarse materiales en una demolición?","<strong>4,00 m</strong>.");
// Art. 74
add(74,"Regla","¿Qué debe hacer el responsable de la demolición con los escombros?","<strong>Retirarlos</strong> y <strong>limpiar los materiales caídos</strong> en fincas linderas o en la vía pública.");
// Art. 75
add(75,"Regla","Para muros de 0,15 m o más, ¿qué ancho tienen los cimientos como regla general?","<strong>0,15 m más</strong> que el ancho del muro que soportan.");
add(75,"Excepción","¿Qué tabiques pueden apoyar directamente sobre el contrapiso?","Los de ancho <strong>no mayor de 0,10 m</strong>.");
add(75,"Caso","Un muro de 0,30 m: ¿qué ancho de cimiento le corresponde?","<strong>0,45 m</strong> (0,30 + 0,15).");
// Art. 76
add(76,"Condición","¿En qué casos puede exigirse un estudio de suelos?","Estructuras de HºAº, metálicas o similares que <strong>superen dos plantas</strong>, o cuando <strong>no se conozca con precisión la resistencia del suelo</strong>.");
add(76,"Facultad","¿Quién puede exigir el estudio de suelos y a cargo de quién se hace?","El <strong>Organismo de Aplicación</strong> (“podrá exigir”); a cargo de <strong>personal competente</strong>.");
// Art. 77
add(77,"Regla","¿Cómo se solicita el permiso de edificación, modificación o demolición?","<strong>Por escrito</strong> a la Municipalidad, en los <strong>formularios</strong> que ella provee.");
add(77,"Facultad","¿Cuándo debe presentarse el título de propiedad con el permiso?","Cuando el <strong>Organismo de Aplicación lo considere necesario</strong>.");
add(77,"Dato","¿A qué ordenanza se ajusta la Municipalidad en materia de permisos de edificación?","A la <strong>Ordenanza 2027/86</strong>.");
// Art. 78
add(78,"Dato","¿Qué documentación se adjunta a la solicitud de permiso?","<strong>Memorias descriptivas</strong> de materiales y su aplicación, y <strong>cuatro copias de los planos</strong>.");
add(78,"Regla","¿Qué normas de presentación deben respetar los planos y qué se les agrega?","Las del <strong>Consejo Profesional de Ingeniería, Agrimensura y Arquitectura de Río Negro</strong>; se agregan las <strong>especificaciones y ocupación del suelo del Código Urbano</strong>.");
// Art. 79
add(79,"Dato","¿Qué piezas deben indicarse en los planos?","<ul><li><strong>Planta general</strong> del edificio y terreno</li><li><strong>Secciones</strong> (mínimo dos)</li><li><strong>Vista de fachada/s</strong></li><li><strong>Croquis de ubicación</strong></li></ul>");
add(79,"Dato","¿En qué escala se presentan planta, secciones y vistas en los planos de obra?","<strong>1:100</strong>.");
add(79,"Dato","¿Cuántas secciones como mínimo deben presentarse en los planos de obra?","<strong>Dos</strong>.");
add(79,"Regla","En los planos de obra, además de los dibujos, ¿qué debe indicarse?","El <strong>destino de cada local</strong> y todas las <strong>medidas y especificaciones técnicas</strong> necesarias.");
add(79,"Regla","¿Quiénes firman los planos y quién los visa?","Profesionales en <strong>Proyecto y Dirección Técnica</strong>; los visa el <strong>Consejo o Colegio Profesional</strong>.");
add(79,"Condición","¿Cuándo es obligatoria la firma del constructor por ejecución de obra?","En los casos de la <strong>Ordenanza 4009/01</strong>.");
// Art. 80
add(80,"Dato","¿En qué tipo de copias se presentan los planos?","<strong>Copias heliográficas</strong>.");
add(80,"Dato","En los planos, ¿cómo se representa lo existente que subsiste y lo que se proyecta?","Subsistente: <strong>perfil reforzado</strong>.<br>Proyectado: <strong>en relleno</strong>.");
add(80,"Dato","En los planos, ¿con qué color se indica lo que se demolerá?","<strong>Amarillo</strong>.");
add(80,"Dato","En los planos, ¿qué colores corresponden a madera, acero o hierro y hormigón?","Madera: <strong>marrón</strong>.<br>Acero o hierro: <strong>azul</strong>.<br>Hormigón: <strong>verde</strong>.");
// Art. 81
add(81,"Regla","¿Qué deben hacer los entes oficiales provinciales o nacionales para construir?","Tramitar el <strong>permiso de construcción ante la Municipalidad de Viedma</strong>.");
// Art. 82
add(82,"Condición","¿Cuándo debe presentarse una planilla de cálculo y según qué modelo?","Cuando la estructura resistente <strong>exige un estudio estático</strong>; según el <strong>modelo del Organismo de Aplicación</strong>.");
// Art. 83
add(83,"Dato","¿Quiénes firman planos, planillas de cálculo y memorias descriptivas?","<strong>Proyectista, calculista y conductor técnico</strong>, el <strong>constructor</strong> y el <strong>propietario</strong>.");
add(83,"Condición","¿Qué requisito deben cumplir los profesionales firmantes y el constructor?","Profesionales: <strong>matriculados en el Consejo Profesional de IAyA de Río Negro</strong>.<br>Constructor: <strong>inscripto en el Registro del Art. 93</strong>.");
// Art. 84
add(84,"Regla","¿Qué ocurre con un plano que no se ajusta al Código?","Se <strong>devuelve al interesado</strong> para modificarlo o rehacerlo.");
add(84,"Dato","¿En qué plazo debe presentarse de nuevo el plano devuelto?","En <strong>no más de 60 días</strong>.");
// Art. 85
add(85,"Condición","¿Qué debe ocurrir antes de entregar las copias aprobadas del permiso de construcción?","<strong>Abonar los derechos</strong> y que se <strong>apruebe toda la documentación</strong>.");
add(85,"Dato","¿Cómo se entregan las copias aprobadas de la documentación de obra?","<strong>Selladas con el número de permiso</strong> de construcción.");
// Art. 86
add(86,"Prohibición","¿Qué está prohibido antes de contar con el permiso?","<strong>Iniciar cualquier obra</strong>.");
add(86,"Regla","¿Qué documentación debe estar en la obra y hasta cuándo?","Una <strong>copia de la documentación visada</strong> y las <strong>planillas de autorización</strong> municipales, a disposición de los inspectores <strong>hasta la terminación</strong>.");
// Art. 87
add(87,"Condición","¿Cuándo caduca un permiso de edificación?","Si la obra <strong>no se comenzó dentro de seis meses</strong> desde la <strong>fecha de pago de los derechos</strong>.");
add(87,"Regla","Caducado el permiso, ¿qué debe hacerse?","<strong>Solicitarlo nuevamente</strong> y <strong>abonar por segunda vez</strong> los derechos.");
// Art. 88
add(88,"Prohibición","¿Qué cambios no pueden hacerse sin previo permiso?","<strong>Modificaciones que alteren los planos aprobados</strong> o <strong>ampliaciones</strong> que aumenten la superficie cubierta y el valor de la propiedad.");
add(88,"Regla","¿Quiénes no pueden modificar los planos aprobados sin permiso, y cómo se pide ese permiso?","El <strong>propietario o el constructor</strong>; se pide <strong>presentando la modificación</strong>.");
// Art. 89
add(89,"Condición","¿Qué situación lleva a archivar el expediente de una obra?","Obra <strong>suspendida seis meses</strong> sin <strong>notificar por escrito</strong> las razones a la Municipalidad.");
add(89,"Regla","Antes de archivar el expediente de una obra suspendida sin aviso, ¿qué hace la Municipalidad?","<strong>Inspecciona</strong> y deja <strong>constancia del estado</strong> de los trabajos.");
add(89,"Regla","Archivado el expediente de una obra suspendida, ¿qué necesita el propietario para continuar?","Un <strong>nuevo permiso</strong>.");
// Art. 90
add(90,"Facultad","Si la suspensión de una obra se notifica por escrito, ¿qué puede hacer la Municipalidad?","<strong>Prorrogar la vigencia del permiso</strong>.");
add(90,"Dato","Obra suspendida con aviso por escrito: ¿qué plazo puede tener la prórroga del permiso?","El que fije la Municipalidad a su criterio, <strong>no inferior a seis meses</strong>.");
add(90,"Distinción","Obra suspendida 6 meses: ¿qué diferencia hay entre notificar o no por escrito?","Sin notificar: se <strong>archiva el expediente</strong> y hace falta <strong>nuevo permiso</strong> (Art. 89).<br>Notificando: puede <strong>prorrogarse el permiso</strong>, por no menos de 6 meses (Art. 90).");
// Art. 91
add(91,"Regla","¿Quiénes firman la solicitud de cambio de conductor técnico?","El <strong>propietario</strong>, el <strong>nuevo conductor técnico</strong> y el <strong>conductor saliente</strong>.");
add(91,"Regla","¿Con qué fin se presenta a la Municipalidad la solicitud de cambio de conductor técnico?","Para su <strong>conocimiento</strong>.");
add(91,"Regla","Tras el cambio de conductor técnico, ¿quién firma la documentación y quién la visa?","La firma el <strong>nuevo Director Técnico</strong> y la visa el <strong>Colegio o Consejo</strong>.");
// Art. 92
add(92,"Dato","¿Qué medidas mínimas tiene el letrero de obra y dónde se coloca?","<strong>0,40 m × 0,60 m</strong>, al <strong>frente de la obra en lugar visible</strong>.");
add(92,"Dato","¿Qué normas regulan el texto del letrero de obra?","La <strong>Ley 442</strong> y su <strong>Decreto Reglamentario 120/74</strong>.");
// Art. 93
add(93,"Regla","¿Qué deben registrar los constructores y dónde?","Su <strong>firma y domicilio</strong> en un <strong>libro especial</strong> del Organismo de Aplicación.");
// Art. 94
add(94,"Dato","¿En qué plazo debe el constructor comunicar su cambio de domicilio?","Dentro de los <strong>ocho días</strong> de producido.");
// Art. 95
add(95,"Regla","¿De qué responden los constructores ante la Municipalidad?","De <strong>todo lo que ocurra en la ejecución</strong> de la obra y del <strong>fiel cumplimiento del Código</strong> y de la <strong>Ley 442</strong>.");
// Art. 96
add(96,"Facultad","¿Cuándo puede inspeccionar el Organismo de Aplicación y con qué fin?","<strong>En el momento que considere necesario</strong>, para <strong>verificar el cumplimiento</strong> de las normas.");
// Art. 97
add(97,"Dato","¿En qué plazo se pide la inspección de una obra terminada que exigió planos?","Dentro de los <strong>quince días</strong> de terminada.");
add(97,"Regla","¿Cómo se solicita la inspección final de una obra terminada?","En <strong>formularios especiales</strong> firmados por el <strong>propietario y el conductor técnico</strong>.");
// Art. 98
add(98,"Dato","Obra sin permiso municipal: ¿qué multa corresponde y hasta cuándo?","De <strong>1/5 a 1/2 del sueldo mínimo municipal</strong>, hasta que <strong>regularicen el trámite</strong>.");
add(98,"Regla","¿Quiénes son responsables por obras sin permiso?","El <strong>propietario y/o director técnico o constructor</strong>.");
// Art. 99
add(99,"Dato","Modificaciones o ampliaciones de los planos aprobados hechas sin permiso: ¿qué multa corresponde?","Multa <strong>diaria</strong> de <strong>1/5 a un sueldo mínimo municipal</strong>, hasta regularizar.");
// Art. 100
add(100,"Dato","Constructor que autoriza habilitar la obra sin certificado de inspección final: ¿qué multa corresponde?","Multa <strong>diaria de ¼ de sueldo mínimo municipal</strong>.");
add(100,"Distinción","Compará las multas por obra sin permiso, por modificación sin permiso y por habilitar sin inspección final.","Art. 98, sin permiso: <strong>1/5 a 1/2</strong> sueldo mínimo.<br>Art. 99, modificación sin permiso: <strong>diaria de 1/5 a 1</strong> sueldo.<br>Art. 100, habilitar sin final de obra: <strong>diaria de ¼</strong> sueldo.");
// Art. 101
add(101,"Facultad","¿Qué sanción puede disponer la Municipalidad sobre constructores y directores técnicos, y a quién la comunica?","La <strong>inhabilitación de su firma</strong>, comunicándola al <strong>Consejo Profesional de IAyA de Río Negro</strong>.");
add(101,"Condición","¿En qué casos procede la inhabilitación de firma?","<ul><li><strong>Infracciones repetidas</strong> al Código</li><li>Continuar una obra <strong>desacatando la suspensión</strong> ordenada</li><li><strong>No vigilar</strong> la ejecución, directamente o por capataz o encargado</li></ul>");
add(101,"Dato","¿Qué escala de suspensión de firma rige según la reincidencia?","1ª vez: <strong>3 meses</strong>.<br>2ª: <strong>6 meses</strong>.<br>3ª: <strong>1 año</strong>.<br>Nueva reincidencia: <strong>inhabilitación permanente</strong>.");
// Art. 102
add(102,"Dato","Obras en violación al Código: ¿qué multa corresponde y de qué depende?","De <strong>10 a 20 sueldos mínimos municipales</strong>, según la <strong>gravedad</strong>.");
add(102,"Regla","Obras en violación al Código: además de la multa, ¿qué ordena el Organismo de Aplicación?","La <strong>modificación y/o demolición</strong> de lo construido en infracción.");
add(102,"Dato","¿Qué plazo máximo tiene la orden de modificar o demoler lo construido en infracción?","<strong>120 días corridos</strong>.");
add(102,"Dato","Vencido el plazo para modificar o demoler lo construido en infracción, ¿qué consecuencias hay?","Multa de <strong>40 sueldos mínimos</strong> y <strong>demolición por la Municipalidad a cargo de los responsables</strong>.");
add(102,"Regla","Obras en violación al Código (multa de 10 a 20 sueldos): ¿quiénes son los responsables?","El <strong>titular</strong> y el <strong>representante técnico</strong>.");
// Art. 103
add(103,"Condición","¿Cuándo puede la Municipalidad demoler sin más trámite?","Ante <strong>peligro inminente de derrumbe</strong> de una pared o edificio.");
add(103,"Regla","En una demolición por peligro inminente de derrumbe, ¿quién la ejecuta, a cargo de quién y con qué formalidad?","La ejecuta la Municipalidad <strong>por sus propios organismos</strong>, a cargo del <strong>propietario</strong>, con sólo <strong>levantar acta</strong> al momento de demoler.");
// Art. 104
add(104,"Regla","¿Qué disposiciones deroga el Código?","<strong>Todas las disposiciones municipales que se le opongan</strong>.");
// Art. 105
add(105,"Facultad","¿Quién reglamenta el Código y qué puede incorporar?","La <strong>Municipalidad de Viedma</strong>, en forma integral; puede incorporar <strong>normas de su actualización</strong>.");
add(105,"Condición","Para incorporar normas por actualización, ¿a quién debe consultar la Municipalidad?","A la <strong>Subsecretaría de Vivienda y Desarrollo Urbano</strong> de Río Negro.");
// Art. 106
add(106,"Regla","¿Qué normas se aplican a los trámites iniciados antes de la vigencia del Código?","Las <strong>vigentes al momento de la presentación</strong>.");
add(106,"Condición","¿Qué antigüedad máxima deben tener los trámites iniciados antes del Código para regirse por las normas anteriores?","<strong>No más de seis meses</strong> antes de la vigencia del Código.");
}
});
